(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["3-1"] = [{"a": [1, 2, 3, 4], "v": 2, "p": 401, "ev": 2, "ep": 410, "sid": 603, "t": "قوله عز وجل: (الم (1) الله لا إله إلا هو الحي القيوم (2) نزل عليك الكتاب بالحق مصدقا لما بين يديه وأنزل التوراة والإنجيل (3) من قبل هدى للناس وأنزل الفرقان).\nالأصل في حروف التهجي السكون، وكان حكم الميم\nحكم غيره لكن حرك لالتقاء الساكنين، وفتح استثقالا للكسرة\nفيه من أجل الياء قبله، ومن قال: إنما فتح لأنه ألقي عليه\nحركة الهمزة فخطأ؟ لأن هذه الهمزة تسقط في الدرج إلا في\nقولهم: يا ألله، والهمزة التي تلقى حركتها على ما قبلها هي\n⟦2:402⟧\nالثابتة في الوصل والوقف، نحو: من ابوك؟ إذا قلت: من\nأبوك؟.\nوروي عن عاصم وغيره سكون الميم وقطع الألف.\nوليس ذلك بصحيح عند النحويين، لكون الألف فيه للوصل.\nوأما موضع إعراب (الم) فمبتدأ وخبره مضمر، أو خبر مبتدؤه\n⟦2:403⟧\nمضمر، ودل على المحذوف منه قوله: ﴿نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ﴾⟪3:3⟫\nفصار كقوله: ﴿الٓمٓ ۝ ذَٰلِكَ ٱلۡكِتَٰبُ﴾⟪2:1-2⟫ وقال بعضهم: (الم)\nمبتدأ وخبره ﴿نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ﴾⟪3:3⟫، ونسب تعالى التنزيل إلى\nالحروف، تنبيها أنه منها، وأن عجزكم عن الإتيان بمثله دلالة\nلكم أنه كلام الله دون كلام الخلق.\nوقد تقدم أن أهل اللغة قالوا:\nالكتاب سمي لكتب الحروف بعضها إلى بعض، أي ضمها.\nوقيل: سمي المعنى الثابت كتاب تشبيها بالمكتوب، وعلى هذا قوله\nتعالى: ﴿مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ﴾⟪57:22⟫.\n⟦2:404⟧\nويقال: لكل موجب كتاب.\nوروي أنه نزل ذلك في وفد نجران الذين أتوا النبي - صلى الله عليه وسلم -، فخاصموا في عيسى عليه الصلاة والسلام، فقال النبي - صلى الله عليه وسلم -: \"ألستم تعلمون أن الله حي لا يموت، وأن عيسى يموت، وأن\nالله لا يخفى عليه شيء، وقد كان عيسى يخفى عليه أشياء، وأن\nعيسى صور في الرحم كيف شاء الله؟ \" - نبههم بذلك أنه لا يصح\nأن يكون عيسى مع كونه بهذه الصفات إلها - فأنزل الله تعالى\nالآية.\n⟦2:405⟧\nفقوله: ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪3:2⟫ ليس بدعوى يحتاج فيها إلى\nدلالة من خارج، بل هو في نفسه دلالة لازمة وحجة واضحة.\nفإن معنى قوله: (الله) أي هو الذي يحق له العبادة، أي الذي\nتأله الأشياء إليه، وكان الكفار يقولون: الأشياء ثلاثة: عابد\nغير معبود، ومعبود عابد، ومعبود غير عابد؟ وهو الله تعالى.\nفبين تعالى بهذا أن المستحق للعبادة على الإطلاق هو الذي\nلا إله إلا هو، وأكد ذلك بقوله: ﴿ٱلۡحَيُّ ٱلۡقَيُّومُ﴾⟪3:2⟫، والحي في صفات الله\nمعناه الذي لا يجوز عليه الموت، وبه حياة كل حي، وإذا استعمل\nفي غيره فعلى معنى قبول الحياة منه تعالى.\nوالقيوم: هو القائم بحفظ كل شيء، والمعطي له ما به قوامه، وهو المعنى المذكور\n⟦2:406⟧\nفي قوله تعالى: ﴿أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ﴾⟪20:50⟫.\nوقوله: ﴿أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ﴾⟪13:33⟫.\nوالحق أبلغ من الصدق،. لأن كل صدق حق، وليس كل حق\nصدقا، ويتناول الأحكام والواجبات من حقوق الله وحقوق\nالناس. والصدق من أخبار الأمم السالفة والآنفة، والحق الذي هو\nالجد. والتوراة عند الكوفيين تفعلة وليس في كلام العرب تفعلة\nبوجه، وإنما هو تفعلة نحو تتفلة وتفعلة نحو تكرمة.\n⟦2:407⟧\nوقيل : أصله تفعلة، فعدل عن الكسرة إلى الفتحة.\nوعند البصريين هي فوعلة نحو: حوقلة، وصومعة. فأبدل\nمن الواو تاء، كما أبدل في توصية وتيقور من الوقار.\nوالإنجيل: إفعيل من النجل، والنجل مستعمل في الأصل\nوفي الولد.\n⟦2:408⟧\nإن قيل: لم قال: ﴿نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ﴾⟪3:3⟫ (وأنزل التوراة)؟\nقيل: قد يقال: (نزل) و (أنزل) بمعنى. لكن خص الكتاب\nبالتنزيل لأمرين:\nأحدهما: أن هذا الكتاب لما كان حكمه مؤبدا، والتنزيل بناء المبالغة\nخص به تنبيها على هذا المعنى، وليس ذلك حكم الكتابين قبل.\nوالثاني: أن هذا الكتاب أنزل شيئا فشيئا، والكتابين أنزل كل\nواحد منهما جملة.\nوقوله: ﴿مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ﴾⟪3:3⟫ يعني الكتب المتقدمة، وخص التوراة والإنجيل بالذكر، وإن كانا قد دخلا في عموم ما بين يديه تشريفا لهما.\nو (مصدقا) حال للمنزل أو للمنزل.\n⟦2:409⟧\nوقوله: ﴿وَأَنزَلَ ٱلۡفُرۡقَانَۗ﴾⟪3:4⟫ أي أنزل في كتبه ما يفرق به بين\nالحق والباطل في الاعتقادات، والخير والشر في الأفعال، نحو\nقوله: ﴿تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ﴾⟪16:89⟫: وكل كتاب لئه فرقان.\nوقيل: الفرقان مخصوص به القرآن خاصة، وتخصيصه بالذكر بعدما\nتقدم تنبية على إثبات المعنيين له، كقوله تعالى: ﴿وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ﴾⟪2:185⟫.\nإن قيل: كيف يكون القرآن مصدقا لما بين يديه، وهو ناسخ\n⟦2:410⟧\nلعامة أحكامه؟\nقيل: تصديقه إياه تحقيقه أنه من جهة الله، ومطابقته إياه في\nكونه داعيا إلى التوحيد وفعل الخير ونحو ذلك، وإلى أنواع\nالعبادات دون قدرها وهيكلها وكيف إيقاعها."}, {"a": [5], "v": 2, "p": 410, "ev": 2, "ep": 410, "sid": 612, "t": "قوله عز وجل: (إن الله لا يخفى عليه شيء في الأرض ولا في السماء (5).\nلم يعن بآيات الله كتابه فقط، بل كل آية دالة عليه: عقلية\nكانت أم سمعية، ففي كل شيء له عبرة، ونبه أنه لا يتهيأ\nلأحد منعه من عذاب من أراد."}, {"a": [6], "v": 2, "p": 410, "ev": 2, "ep": 412, "sid": 612, "t": "قوله تعالى: (هو الذي يصوركم في الأرحام كيف يشاء لا إله إلا هو العزيز الحكيم (6)\n⟦2:411⟧\nالصورة من صيرته أي أحلته، وهي هيئة معقولة أو محسوسة.\nوالصبغة نحوها، إلا أن أكثر ما يستعمل في المحسوسة.\nإن قيل: كيف قال في موضع: (وصوركم) على لفظ الماضي.\nوقال هاهنا بلفظ الاستقبال؟\nقيل: أما أولا فلا اعتبار بالأزمنة في أفعاله تعالى، وإنما استعمال الألفاظ فيه الدالة على الأزمنة\nبحسب اللغات، وأيضا فقوله: صوركم إنما هو على سبيل\nالتقدير، وأن فعله تعالى في حكم ما قد فرغ منه، كقوله: ﴿أَتَىٰٓ أَمۡرُ ٱللَّهِ﴾⟪16:1⟫، وقوله: يصور على حسب ما يظهر لنا حالا، فحالا،\n⟦2:412⟧\nإن قيل: لم قال: ﴿لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ﴾⟪3:5⟫\nولم يقل: هو عالم بكل شيء؟\nقيل: لأن الوصف بأنه \"لا يخفى عليه شيء\" أبلغ من قوله \"يعلم \"\nفي الأصل، وإن كان استعمال اللفظتين فيه يفيدان معنى واحدا.\nوتخصيص الأرض والسماء لكون ذكرهما أهول بالإضافة إلينا، وفيه دلالة على كل شيء، وإنما كرر قوله: ﴿لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪3:6⟫ لأنه لما ذكر ما تقدم\nدليلا على كون عيسى مخلوقا، وكونه تعالى خالقا نبه بقوله:\n﴿لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪3:6⟫ أن لا معبود سواه، وأنه العزيز في نقمته.\nالحكيم في أمره، لا حاجة به إلى ولد، ولا حكمة تقتضي ذلك."}, {"a": [7], "v": 2, "p": 412, "ev": 2, "ep": 430, "sid": 614, "t": "قوله عز وجل: (هو الذي أنزل عليك الكتاب منه آيات محكمات هن أم الكتاب وأخر متشابهات فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله وما يعلم تأويله إلا الله والراسخون في العلم يقولون آمنا به كل من عند ربنا وما يذكر إلا أولو الألباب (7).\n⟦2:413⟧\nالزيغ: الميل عن الاستقامة إلى أحد الجانبين، ومنه زاغ البصر.\nوزاغت الشمس عن كبد السماء، وزاغ قلبه، وزاغ وزال ومال.\nتتقارب، لكن زاغ لا تقال إلا فيما كان عن حق إلى باطل.\nوالتأويل: آخر الشيء ومآله، وقد تقدم الفرق بينه وبين التفسير.\nوالمحكم قد وصف به القرآن على وجهين:\nأحدهما: عام في جميعه، نحو ﴿كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ﴾⟪11:1⟫\nوقوله: ﴿تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ﴾ ويعني بذلك المتقن.\nنحو: بناء محكم، وعقد محكم.\nوالثاني: ما وصف به بعض الكتاب المذكور في قوله: ﴿مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ﴾⟪3:7⟫ وهو ما لا يصعب على العالم معرفته لفظا أو معنى،\n⟦2:414⟧\nوقيل: ما لا يحتاج العالم في معرفته إلى تكلف نظر ، وعكسه\nالمتشابه، والكلام في أحوال المحكم والمتشابه - مشكل.\nولابد من إيراد جملة ينكشف بها ذلك، فيقال وبالله التوفيق:\nالكلام من جهة الإحكام والتشابه على ضربين:\nأحدهما: ما يرجع إلى ذات المحكم والمتشابه في نفسه.\nوالثاني: ما يرجع إلى أمر ما يعرض لهما.\nفالأول على أربعة أضرب:\nأحدها: محكم من جهة اللفظ والمعنى، نحو قوله تعالى:\n﴿تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ﴾⟪6:151⟫\n⟦2:415⟧\nالثاني: مشابه من جهتيهما، نحو قوله: ﴿فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ﴾⟪6:125⟫\nوالثالث: متشابه في اللفظ محكم في المعنى، نحو قوله:\n﴿وَجَآءَ رَبُّكَ﴾⟪89:22⟫\n⟦2:416⟧\nوالرابع متشابه في المعنى محكم في اللفظ، نحو:\nالساعة، والملائكة.\nوقد تجعل هذه الأقسام ثلاثة: أحدها: محكم على الإطلاق.\nومتشابه على الإطلاق، ومحكم من وجه.\nوالمتشابه ضربان:\nأحدهما: من جهة اللفظ، والآخر: من جهة المعنى.\nوالمتشابه من جهة اللفظ ضربان:\nأحدهما: يرجع إلى مفردات الألفاظ.\nوذلك إما من جهة غرابة اللفظ، نحو (الأب) ونحو (يزفون)،\n⟦2:417⟧\nوإما من تشارك في اللفظ: كاليد والعين والوجه.\nالثاني: يرجع إلى جملة الكلام المركب، وذلك ثلاثة أضرب:\nأحدها: اختصار الكلام نحو ﴿وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ﴾⟪4:3⟫.\nوالثاني: تطويله نحو ﴿كَمِثۡلِهِۦ شَيۡءٞۖ﴾⟪42:11⟫.\nوالثالث: إغلاق نظمه، نحو: ﴿وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ ۝ قَيِّمٗا﴾⟪18:1-2⟫.\nوالمتشابه من جهة المعنى ضربان:\nأحدها: د قة المعنى، كأوصاف الباري تعالى، وأوصاف\n⟦2:418⟧\nالقيامة.\nوالثاني: ترك الترتيب، نحو قوله: ﴿وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ﴾⟪48:25⟫ إلى قوله: ﴿لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ﴾⟪48:25⟫.\n⟦2:419⟧\nوما يرجع إلى اللفظ والمعنى معا، فأقسامه بحسب تركيب بعض\nوجوه اللفظ مع بعض وجوه المعنى، نحو: غرابة اللفظ مع دقة\nالمعنى، وذلك ستة أقسام، وأما المتشابه من جهة ما يعرض للفظ\nفخمسة أقسام: أحدها: من جهة الكمية: كالعموم والخصوص.\nوالثاني: من طريق الكيفية: كالوجوب والندب، والثالث:\nمن جهة الزمان: كالناسخ والمنسوخ، والرابع: من جهة\nالمكان: كالمواضع، والأمور التي نزلت فيها، نحو قوله:\n﴿وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا﴾⟪2:189⟫.\nوقوله: ﴿إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ﴾⟪9:37⟫، فإنه يحتاج في معرفة ذلك\n⟦2:420⟧\nإلى معرفة عادتهم في الجاهلية.\nوالخامس: من جهة الإضافة.\nوهي الشروط التي بها يصح الفعل أو يفسد: كشروط العبادات\nوالأنكحة، وهذه الجملة من المحكم والمتشابه إذ تصورت\nعلم أن جميع ما يذكره المفسرون لا يخرج منها، نحو قول من\nقال: المتشابه نحو (الم) وما أشبهه، وقول مجاهد:\nالمحكم ما فيه الحلال والحرام، والمتشابه ما سواه.\nوقول\n⟦2:421⟧\nقتادة: المحكم الناسخ الذي يعمل به، والمتشابه: المنسوخ.\nوقول الأصم: المحكمات ما حججه ظاهر، والمتشابه ما\nحججه غامضه.\nوقول غيرهم: المحكم ما أجمع على تأويله،\n⟦2:422⟧\nوالمتشابه ما اختلف فيه، فكل هذه الأقوال مثالات لبعض\nما انطوت عليه هذه الجملة. ثم جميع ما ذكرنا من المتشابه على\nثلاثة أضرب: ضرب لا مرية فيه أن لا سبيل إلى المراد بتأويله.\nوهو بعض ما تعرض فيه الشبهة من جهة المعنى كمجيء الساعة.\nوحقيقة ذاته.\nوضرب لا خلاف أن للإنسان سبيلا إلى معرفته، وذلك ما كان اشتباهه من جهة ما يعرض له من عموم وخصوص\nووجوب وندب وغير ذلك مما تقدم ذكره، وكذا ما تعرض فيه\nالشبهة من جهة غرابة اللفظ، وما هو متردد بين الأمرين، يجوز\nأن يختص بمعرفته بعض الراسخين في العلم نحو علي\n⟦2:423⟧\nوابن عباس وغيرهما مما قال النبي - صلى الله عليه وسلم -: \"اللهم فقهه في\nالدين وعلمه التأويل\".\nوهذه الجملة إذا تصورت\n⟦2:424⟧\nعلم أن من رأى الوقف على قوله: ﴿وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ﴾⟪3:7⟫\nواستأنف ما بعده فلنظره إلى الضرب الأول من المتشابه، ومن\nوصل ذلك وجعل قوله: (الراسخون) عالين به، فلنظره إلى الضرب\nالثاني، والأظهر من الآية القول الأول، وما قال بعضهم:\nإنه لو جاز أن يخاطبنا ثم لا يعرفنا مراده، لجاز أن يخاطبنا بكلام\nالزنج والروم، فالجواب عنه: أن كلام الروم والزنج لا يعلم\n⟦2:425⟧\nمنه المراد مجملا، ولا مفصلا، والمتشابه يعلم منه مراده مجملا\nوإن لم نعلمه مفصلا، لأن كل آية قد فسرها المفسرون على أوجه.\nفمعلوم أن المراد لا يخرج منه، ثم تعيين مراد الله تعالى منها غير\nفمعلوم، وهذا ظاهر.\nعلى أنه لم يكن يمتنع أن يكلفنا تعالى\n⟦2:426⟧\nتلاوة أحرف لا نعرف معناها، فيثيبنا على تلاوتها، كما يكلفنا\nأفعالا لا نعرف وجه الحكمة فيها، ليثيبنا عليها، فالتلاوة\nفعل يختص باللسان، ومن جعل قوله: (والراسخون) معطوفا\nجعل قوله: (يقولون) في موضع الحال للمعطوف دون المعطوف\nعليه، كما في قوله: ﴿وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا﴾⟪89:22⟫ حال\nللمعطوف دون المعطوف عليه.\nإن قيل: لم خص الراسخين بأنهم يقولون آمنا به؟\nقيل: لأن معرفة ما للإنسان سبيل إلى معرفته مما لا سبيل له إلى معرفته هو\nمن علوم الراسخين، لأن الحكماء هم الذين يميزون بين ما\nيمكن علمه وما لا يمكن أن يعلم، وما الذي يدرك إن طلب\n⟦2:427⟧\nوالذي لا يدرك، وعلى أي غاية يجب أن يقف طالب العلم، وأي\nمكان يتجاوزه، وهذا أشرف منزلة للحكماء، ولذلك قالت\nعائشة رضي الله عنها: \"من رسوخ علمهم الإيمان بمحكمه\nومتشابهه وإن لم يعلموا تأويله \"\nإن قيل: ما فائدة الإتيان بالمتشابه فى القرآن؟\nقيل: فوائد جمة، منها: أن يبين تشريف\nالعلماء بتميزهم عن غيرهم، ومنها: رياضة العقول في تعرفها.\nومنها: استحقاق الثواب بتعب الفكر فيه، ومنها: إظهار شرف\n⟦2:428⟧\nالفكر، ليعلم أنه لم يجعل الإنسان عبثا، ومنها: حث من أخبر\nالله عنهم أنهم قالوا: ﴿لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ﴾⟪41:26⟫ على أن\nيتدبره، لأنهم إذا سمعوا ما في ظاهره التنافي تأملوه طلبا لرده.\nفيصير ذلك سببا أن يعرفوه لمعرفتهم بإعجازهم ولزوم الحجة به.\nومنها: أن يصير سببا لاعتراف الإنسان بعجزه ومعرفة نقصه.\nومنها: أن يصير الناس تبعا للأنبياء وأولي الأمر الذين حث\nعلى اتباعهم لقو له: ﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ﴾⟪4:83⟫\nوقوله: ﴿فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ﴾⟪3:7⟫\nفذم لهم بأنهم لزيغهم \"يتحرون طلب الفتنة، وقدم\n⟦2:429⟧\nذكر الفتنة تنبيها أن قصدهم إلى إيقاع الفتنة قبل طلب تأويله.\nوهذا القصد باتفاق أهل العقول كلها مذموم.\nفإن قيل: هب أن اتباع طلب الفتنة مذموم.\nفكيف ذموا بابتغاء تأويله؟\nقيل: طلب التأويل من نفس المتشابه مذموم.\nإذ لا سبيل إلى تبينه منه، وإنما طلب الحق يجب أن يكون\nبردة إلى المحكم إلى الرسول وإلى أولي الأمر.\nحسب ما نبه عليه تعالى بقوله: (﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ﴾⟪4:83⟫ الآية.\nوكل له حالتان:\nأحدهما: أن يكون تابعا على طريق التأكيد، فلا يحذف منه ضمير\nما أكد به، نحو: مررت بالقوم كلهم.\nوالثاني: أن تجعله مخبرا عنه، فيصح الحذف منه إيجازا، نحو: ﴿إِنَّا كُلّٞ فِيهَآ﴾⟪40:48⟫، وفي\n⟦2:430⟧\nقوله: ﴿كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ﴾⟪3:7⟫ على هذا.\nوالتذكر هاهنا: هو الاتعاظ، ولم يجعل ذلك إلا لصفو\nالخلائق، لما تقدم أن معرفة ما يصح أن يطلب ويعلم مما لا يصح\nفيه ذلك أشرف منزلة في العلم."}, {"a": [8], "v": 2, "p": 430, "ev": 2, "ep": 434, "sid": 632, "t": "قوله عز وجل: (ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب (8)\nالوهاب: قيل معناه: لا تزغ قلوبنا عن الثواب في الآخرة.\nوقيل: لا تنسبها إلى الزيغ، ولا تحكم عليها بذلك.\nوقيل: لا تفعل بنا من الإكرام ما يؤدي إلى الزيغ.\nفكأن الإزاغة إعطاء الخيرات الدنيوية المثبطة عن الخيرات الأخروية\nالمشار إليه بقوله تعالى: ﴿وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ﴾⟪42:27⟫\nولهذا قال أمير المؤمنين رضي الله عنه: \"من وسع\n⟦2:431⟧\nعليه دنياه ولم يعلم أنه مكر به، فهو مخدوع عن عقله \".\nوقيل معناه: لا تكلفنا أمرا شاقا: كقتل النفس، والخروج من الديار\nالمذكورين في قوله: ﴿وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ﴾⟪4:66⟫.\nوقيل: معناه لا تمنعنا التوفيق، فجعل منع التوفيق إزاغة للقلوب من حيث\nإنه يؤدي إليها، إشارة إلى ما قيل: أقطع ما يكون المجتهد إذا\n⟦2:432⟧\nخذله التوفيق، وإياه قصد الشاعر بقوله:\nإذا لم يكن عون من الله للفتى. . . فأكثر ما يجني عليه اجتهاده\nونحو قوله: ﴿لَا تُزِغۡ قُلُوبَنَا﴾⟪3:8⟫ ما روي أن النبي - صلى الله عليه وسلم - كان يقول: \"يا مقلب القلوب ثبت قلبي على دينك\"\nفقالت له عائشة: وهل تقلب القلوب؟\nفقال: \"إن قلوب العباد بين أصبعين من أصابع الرحمن يقلبها كيف يشاء \".\nوالهبة: تمليك الشيء غيره من غير ثمن.\n⟦2:433⟧\nولدن: فيه لغات، قيل: لدن، ولدن بضمتين، ولدن بفتحتين، ولدن\nبالسكون مع فتح اللام وضمه، وقيل: بكسر النون، وقيل: لد\nبحذف النون، ولدى، ونبه تعالى بقوله: ﴿وَهَبۡ لَنَا﴾⟪3:8⟫ أن من\nحق العبد أن لا يلفت له إلى شيء من العمل وطلب العوض به.\nبل يرجو رجاء المفاليس الطالبين للتفضل والهبة لا العوض،\n⟦2:434⟧\nوإنما قال: ﴿مِن لَّدُنكَ﴾⟪3:8⟫ لأنه لما كانت الهبة ضربين:\nهبة عن عوض، وهبة لا عن عوض.\nنبه بقوله: (لدنك) أن هذه الهبة اعتراف أن بتفضله\nيدرك ما يدرك في الدنيا والآخرة، نحو قوله:\n﴿وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ﴾⟪7:43⟫."}, {"a": [9], "v": 2, "p": 434, "ev": 2, "ep": 436, "sid": 636, "t": "قوله عز وجل: (ربنا إنك جامع الناس ليوم لا ريب فيه إن الله لا يخلف الميعاد (9)\nإن قيل: كيف قال: ﴿لَّا رَيۡبَ فِيهِۚ﴾⟪3:9⟫ وقد وقع فيه ريب الملحدة\nوالمغلطة حتى حكى الله تعالى في إبطالهم إياه ما حكى؟\nقيل: قد تقدم في مبتدأ سورة\n⟦2:435⟧\nالبقرة الفرق بين الريب والإرابة (1)، وأن الذي وقع منهم الإرابة لا\nالريب، وقوله: ﴿إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ﴾⟪3:9⟫ يصح أن يكون\nاستئنافا، من الله، وأن يكون من جملة قولهم، والحكاية\nعنهم، والفائدة في العدول عن الخطاب إلى الخبر، وتخصيص\nلفظ \"الله \" بذلك تنبيا أن الذي اختصصنا بعبادته هذا فعله.\nولم يرد بقوله: ﴿إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ﴾⟪3:9⟫ في جمعنا فقط، بل في\nكل وعد، فإن ذلك كالعلة لما قدمه، كأنه قيل: الله لا يخلف\n⟦2:436⟧\nالميعاد، وقد وعدنا أن يجمعنا ليوم لا ريب فيه، فإذا هو جامعنا\nلا محالة.\nإن قيل: لم قال: ﴿لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ﴾⟪3:9⟫، ولم يقل (في)؟\nقيل: لأنه أراد بقوله جامع الناس: حافظهم ومحصيهم لذلك اليوم.\nكما قال: ﴿لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدّٗا﴾⟪19:94⟫، وكقوله: ﴿إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ﴾⟪14:42⟫."}, {"a": [10], "v": 2, "p": 436, "ev": 2, "ep": 437, "sid": 638, "t": "قوله عز وجل: (إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئا وأولئك هم وقود النار (10)\nبين أن أعراض الدنيا وإن كانت نافعة بعض الأمور الدنيا.\nفليست مغنية عن الكافرين يوم القيامة، كقوله: ﴿مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ﴾⟪69:28⟫\nفإن قيل: فهل يغني عن المسلم حتى خص الكافرين في هذا المكان؟\nقيل: بلى، لأنه إذا تحرى في ذلك أحكامه كان أحد معاونه في\nوصوله، ولذلك قال: ﴿وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾⟪28:77⟫\nوقوله: (عنهم) لاقتضاء\n⟦2:437⟧\nالكلام معنى الدفع، كأنه قال: لن يغني ذلك دافعا عنهم.\nوقوله: ﴿وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ﴾⟪3:10⟫ كقوله: ﴿وَقُودُهَا ٱلنَّاسُ﴾."}, {"a": [11], "v": 2, "p": 437, "ev": 2, "ep": 439, "sid": 639, "t": "قوله عز وجل: (كدأب آل فرعون والذين من قبلهم كذبوا بآياتنا فأخذهم الله بذنوبهم والله شديد العقاب (11)\nالدأب: العادة التي عليها يدوم صاحبها، وهو أخص من العادة، ومنه\nأدأب في سيره، ولذلك قال الفراء: الدأب لزوم الحال التي فيها.\n⟦2:438⟧\nوقال ابن عباس: هو الصنع، لأن الدأب يقتضي الصنع.\nوقال أبو علي الجبائي: الدأب طول الكون في الشيء كافة.\nككون آل فرعون في النار. والذنب والجرم واحد، لكن الجرم\nيقال اعتبارا بالاكتساب، تشبيها باجترام الثمرة، والذنب\nيقال اعتبارا بما يستحق به في آخره، مأخوذ من الذنب، وعلى\nهذا قيل له: التبعة، وبنحوه سميت العقوبة عقوبة.\nوقيل: سمي الذنب اعتبارا بذنوب الإنسان منه، أي نصيبه.\n⟦2:439⟧\nإن قيل: بم يتعلق قوله: ﴿كَدَأۡبِ ءَالِ فِرۡعَوۡنَ﴾⟪3:11⟫؟\nقيل في ذلك: الوجه الأول: أن يتعلق بقو له: ﴿وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ﴾⟪3:10⟫:\nكحال متقدمي آل فرعون.\nالثاني: بقوله: ﴿لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ﴾⟪3:10⟫\nالثالث: بقوله: ﴿إِنَّ ٱلَّذِينَ كَفَرُواْ﴾⟪3:10⟫ وتقديره: إن\nدأب الذين كفروا كدأب آل فرعون، وتكون ﴿لَن تُغۡنِيَ عَنۡهُمۡ﴾⟪3:10⟫\nحالا للذين.\nوالرابع: أن يجعل قوله: ﴿كَذَّبُواْ بِـَٔايَٰتِنَا﴾⟪3:11⟫ غير داخل\nفي صلة ﴿وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ﴾⟪3:11⟫ فتتعلق به كأنه كذب آل فرعون\nوالذين من قبلهم.\nالخامس: أن يتصل بمحذوف تقديره: دأبهم\nفي كفرهم، واستحقاق عذابهم كدأب آل فرعون."}, {"a": [12], "v": 2, "p": 439, "ev": 2, "ep": 442, "sid": 641, "t": "قوله عز وجل: (قل للذين كفروا ستغلبون وتحشرون إلى جهنم وبئس المهاد (12)\nقال ابن عباس وقتادة وابن إسحاق:\n⟦2:440⟧\nلما قتل من قتل يوم بدر جمع النبي - صلى الله عليه وسلم - اليهود، فدعاهم إلى الإسلام، وحذرهم مثل ما نزل بقريش، فأبوا، وقالوا: لسنا\nكقريش الأغمار إن حاربتنا لتعرفن حالنا، فأنزل الله عز وجل الآية.\nفقوله: ﴿لِّلَّذِينَ كَفَرُواْ﴾⟪3:12⟫ يصح أن يكون يعني\n⟦2:441⟧\nالفريقين: اليهود والمشركين، كقوله: ﴿مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ﴾⟪2:105⟫ ففسر الذين كفروا في الآيتين بهما جميعا.\nوقرئ (ستغلبون) و (سيغلبون)، أما بالياء فنحو ﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ﴾⟪8:38⟫ وقوله ﴿قُل لِّلَّذِينَ ءَامَنُواْ يَغۡفِرُواْ﴾⟪45:14⟫\nوأما بالتاء، فنحو ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ﴾⟪3:81⟫، وقيل: عنى بالذين كفروا\n⟦2:442⟧\nاليهود. وقوله: ستغلبون، للمشركين، فعلى هذا لا يكون\nإلا بالياء.\nإن قيل: كيف أطلق هذا الحكم وقد كان منهم من آمن؟\nقيل: إن الحشر إلى النار متعلق بوجود الكفر منهم، وإذا ارتفع الكفر\nارتفع به الحكم.\nوقوله: ﴿وَبِئۡسَ ٱلۡمِهَادُ﴾⟪3:12⟫ يجوز أن يكون من جملة\nما أمر به أن يقال لهم، ويجوز أن يكون استئناف كلام منه تعالى."}, {"a": [13], "v": 2, "p": 442, "ev": 2, "ep": 448, "sid": 644, "t": "قوله عز وجل: (قد كان لكم آية في فئتين التقتا فئة تقاتل في سبيل الله وأخرى كافرة يرونهم مثليهم رأي العين والله يؤيد بنصره من يشاء إن في ذلك لعبرة لأولي الأبصار (13)\n⟦2:443⟧\nالعبرة: ما يعبر به من الجهل إلى العلم، ومن الحس إلى العقل.\nوأصله من عبور النهر، ومنه: العبارة؛ لأنها جعلت كالمعبر.\nلتأدية المعنى من نفس القائل إلى نفس السامع، وخص التعبير\nبتفسير الرؤيا، وباعتبار المرأون بالشبح، وجعل العبرة للدمعة\nالسائلة، وأصله فعله من عبر.\nوقوله: (فئة) يجوز رفعه على الاستئناف على تقدير: منهم فئة.\nوالجر على البدل، والنصب على الحال، ونحوه مما يجوز فيه الأوجه الثلاثة قول الشاعر:\nوكنت كذي رجلين رجل صحيحة. . . ورجل رمى فيها الزمان فشلت\n⟦2:444⟧\nوإنما يجوز البدل فيما إذا كان بدل بقدر المبدل منه، فأما إذا\nنقص فليس إلا الاستئناف، نحو مررت بثلاثة: صريع وجريح.\nوالآية معطوفة على ما تقدم تقديره: وقل لهم قد كان لهم آية.\nوقرئ (ترونهم) بالتاء على أن يكون خطابا لليهود، أي\nترون المشركين مثلي المسلمين في العدد، ويرون بالياء أي يرون\nالمسلمون الكافرين مثليهم.\nإن قيل: ما وجه ذلك وقد كانوا\n⟦2:445⟧\nثلاثة أمثالهم، فقد روي أن المشركين كانوا تسعمائة وخمسين إلى\nألف، والمسلمين كانوا ثلاثمائة وبضعة عشرة؟\nقيل في ذلك أقوال:\nأحدها: ما قاله الفراء: وهو أن يقول الرجل لغيره:\nاحتاج إلى مثلك، أي احتاج إليك وإلى آخر، وعلى هذا احتاج\nإلى مثليك يكون محتاجا إلى ثلاثة، فكأنه قيل: يرونهم\nثلاثة أمثالهم، وهذا لا يساعده اللفظ، لأنه لو كان كما يقول\nلقال: يرونهم ومثليهم.\nوالثاني: ما قاله ابن عباس: إن الله عز وجل أرى المسلمين أن المشركين هم ستمائة وكسر.\n⟦2:446⟧\nوكان قد أخبر أن المائة من المسلمين - تغلب المائتين، فأراهم\nالمشركين على قدر ما أعلمهم، ليقوي قلوبهم، وأرى المشركين\nأن المسلمين أقل من ذلك.\nومع ذلك ألقى في قلوبهم الرعب،\n⟦2:447⟧\nفكانوا يرون عددا قليلا ورعبا كثيرا، وعلى هذا قال، تعالى:\n﴿وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ﴾⟪8:44⟫.\nوالثالث: أنهم يرونهم مثليهم في الجلادة، أي يرى\nكل واحد منهم أنه أجلد من الآخر بمثلين، وذلك كقولك:\nرأيت فلانا مثلي فلان، فتكون المماثلة راجعة إلى الجلادة، لا\nإلى العدد، وعلى هذا قد حمل قوله عز وجل: ﴿إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ﴾⟪8:43⟫ أي في القوة والعدد، لا في الكثرة والعدد.\n(ويري) هاهنا متعد إلى مفعول واحد بدلالة تعليقه بالعين.\nوقوله: ﴿وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ﴾⟪3:13⟫ أي يكثر تأييده، يقال:\nإدته، أئيده، أيدا، نحو: بعته. أبيعه، بيعا، وآيدته على\nالتكثير، لكن أيدت أكثر استعمالا.\nونصر الله على وجهين: أحدهما بالحجة. والثاني بالغلبة،\n⟦2:448⟧\nوقوله ﴿لِّأُوْلِي ٱلۡأَبۡصَٰرِ﴾⟪3:13⟫ فإنه يعني به البصائر لا الجارحة\nالمذكورة في قوله عز وجل: ﴿فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ﴾⟪22:46⟫\nويعني أن في ذلك اعتبارا للذين هم بخلاف من وصفهم بقوله:\n﴿صُمُّۢ بُكۡمٌ عُمۡيٞ﴾. . ."}, {"a": [14], "v": 2, "p": 448, "ev": 2, "ep": 456, "sid": 650, "t": "قوله عز وجل: (زين للناس حب الشهوات من النساء والبنين والقناطير المقنطرة من الذهب والفضة والخيل المسومة والأنعام والحرث ذلك متاع الحياة الدنيا والله عنده حسن المآب (14).\nالقنطرة من المال مقدار تعبر به الحياة تشبيها بالقنطرة.\nوذلك غير محدود القدر في نفسه، وإنما هو بحسب الإضافة\nكالغنى، فرب إنسان يستغنى بالقليل وآخر لا يستغنى بالكثير،\n⟦2:449⟧\nولما قلنا اختلفوا في حده فقيل: هي أربعون أوقية، وقال\nالحسن: ألف ومائتا دينار، وقيل: ملء مسك ثور ذهبا،\n⟦2:450⟧\nوعلى ذلك عن ابن عباس، وبعضهم: حده يتغير كاختلافهم في حد الغنى.\nكقولهم: درا هم مدرهمة، ودنانير مدنرة، (والخيل) في\n⟦2:451⟧\nالأصل للأفراس والفرسان، وإن كان يستعمل في كل واحد\nمفردا، نحو: \"يا خيل الله اركبي \"، وذلك للفرسان، وقول\nالنبي - صلى الله عليه وسلم -: \"عفوت لكم عن صدقة الخيل والرقيق \"، فكأنه سمي بذلك لما فيه من الخيلاء، فقد قيل: لا يركب أحد فرسا إلا\n⟦2:452⟧\nرأى في نفسه خيلاء، وأصل ذلك من خلت، وهو ظن يقرب\nمن الكذب، ومنه الخيال. والأخيل: الشقراق، لكونه\nمتلونا يخال في كل وقت أن له لونا آخر، ولذلك قيل:\nكأبي براقش كل لو. . . ن لونه يتخيل\nو (المسومة) المرسلة في الرعي، وقيل: المعلمة في\n⟦2:453⟧\nالحرب، يقال: سمي بالقصر وسيمياء بالمد، قال تعالى:\n﴿سِيمَاهُمۡ فِي وُجُوهِهِم﴾⟪48:29⟫، قال الشاعر:\n. . . . . . . . . . . . . . . . . . . . . . . . له سيمياء لا تشق على البصر\nوقال مجاهد: المسومة: المطهمة.\n⟦2:454⟧\nكأنه جعل التضمير لها تسويما، كما جعل (سنا) و (صنعا)\nفي قولهم: (مسنونة) و (مصنوعة).\nوالنعم أصل الإبل.\nفإذا قيل: الأنعام. فقد يتناول الأزواج الثمانية.\nوالشهوة تقال تارة للقوة المشتهية، نحو فلان خامد الشهوة.\nوتارة لانبعاث تلك القوة، وتارة للطعام المشتهى.\nفيقال هذا شهوتي، واختلف في هذا الحب من الذي زينه؟\nمع أنه لا خلاف أن الله عز وجل خالق القوة المشتهية.\nوخالق المشتهى.\nفقال بعضهم: الله عز وجل زينه.\nوذلك لنظره إلى القوة المشتهية أو المشتهى.\nولقوله: ﴿إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا﴾⟪18:7⟫ وإليه ذهب عمر\n⟦2:455⟧\nفإنه روي أنه لما سمع هذه الآية قال: ربنا إنك زينت هذه\nوبينت أن ما بعدها خير منها، فاجعل لعمر وآل عمر الذي هو\nخير منها، وقال بعضهم: زينها الشيطان، وإلى هذا ذهب\nالحسن، فيقول: كيف زينها الله وهو يذمها؟\nومنهم من قال: زين الله منها ما يحسن تناوله، وزين الشيطان ما يقبح، فإن الله عز وجل خلق الإنسان وقوته المشتهية ومشتهياته وأمر أن\n⟦2:456⟧\nيتناول منها على الوجه الذي يجب قدر ما يجب في الوقت الذي\nيجب، ويجعل ذلك ذريعة إلى التوصل به إلى الآخرة، وقيض له\nشيطانا يغره فحذره منه، فمن راعى أمره وتناول ما أبيح له فإنه\nقد لا يتعدى إلى ما زينه الشيطان، وقد تقدم الكلام في بعض\nذلك في قوله: ﴿زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا﴾⟪2:212⟫."}, {"a": [15], "v": 2, "p": 456, "ev": 2, "ep": 458, "sid": 658, "t": "قوله عز وجل: (قل أؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنات تجري من تحتها الأنهار خالدين فيها وأزواج مطهرة ورضوان من الله والله بصير بالعباد (15)\nمنتهى المنبأ قيل هو قوله: ﴿مِّن ذَٰلِكُمۡۖ﴾⟪3:15⟫ وقيل هو (عند ربهم).\nوقيل: هو آخر الآية، وهذه الأقوال على قراءة من رفع (جنات).\nفأما من جرها، فلاشك أن ذلك داخل في جملة الاستفهام، لأنه\n⟦2:457⟧\nبدل من قوله (بخير).\nوقال بعضهم: يجوز أن تكون جنات\nنصبا بدلا من موضع بخير، كقولك: مررت برجل زيدا.\nوقوله: ﴿وَأَزۡوَٰجٞ مُّطَهَّرَةٞ﴾⟪3:15⟫ قد تقدم، وقد نبه بهذه الآية على\nنعمه الثلاثة، الأول: وهي الأدون، وذلك عروض الدنيا.\nوالثاني: الأوسط: وهو الجنة ونعيمها، والثالث: الأعلى، وهو\nرضوان الله المشار إليه بقوله: ﴿وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ﴾⟪53:42⟫.\nوقوله: ﴿هُنَالِكَ ٱلۡوَلَٰيَةُ لِلَّهِ﴾⟪18:44⟫، وقوله: ﴿وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ﴾⟪9:72⟫، ﴿وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ﴾⟪3:15⟫\n⟦2:458⟧\nأي بهممهم وإرادتهم، فهو يجازيهم بحسب ما يستحقونه."}, {"a": [16], "v": 2, "p": 458, "ev": 2, "ep": 460, "sid": 660, "t": "قوله تعالى: (الذين يقولون ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار (16).\n(الذين) جر صفة للعباد، أو رفع على تقدير: هم الذين.\nأو نصب على المدح، وقوله: (يقولون) ليس يعني أن ذلك\nمنهم بالقول فقط، بل باعتقادهم وفعلهم.\n⟦2:459⟧\nإن قيل: ما فائدة: ﴿فَٱغۡفِرۡ لَنَا ذُنُوبَنَا﴾⟪3:16⟫؟\nقيل: أما على مذهب الوعيديين فسؤال ما هو من حكمه أن يفعل ما هو بالمؤمنين\nسئل أو لم يسأل، وقيل: هو فعل ما يقتضي الغفران والوقاية\n⟦2:460⟧\nمن النار، وهو الإقلاع، وإن كان متعلقا بالقول.\nوقيل: هو مسألة لطف، لا يفعله الله بالعبد إلا إذا سأله."}, {"a": [17], "v": 2, "p": 460, "ev": 2, "ep": 465, "sid": 662, "t": "قوله عز وجل: (الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار (17)\nقد تقدم وصف الصبر ومنازله، وأن كل منزل هو أعلى فثوابه أعلى.\nوأن أرفعه صبر العارف الذي هو الرضى والتسليم.\nوالصادقون: هم الذين صدقوا في الاعتقاد والقول والعمل، وذلك غاية الإيمان، والقانت:\n⟦2:461⟧\nالدائم العبادة في السر والجهر، والمنفقون: عني به: في الفرائض\nوالنوافل، ومن المال والبدن، والمستغفرون: طالبو الغفران\nبإتيانهم بالطاعات، وتخصيص الأسحار لكون العبادة فيها أشق\nوالقلوب أحضر وأرق.\nوروى جعفر بن محمد: أن من صلى من الليل، ثم استغفر في آخره سبعين مرة، كتب من المستغفرين\n⟦2:462⟧\nبالأسحار، وروي أن ابن عمر كان يصئي فإذا أسحر قعد\nيستغفر، وقال زيد بن أسلم: المستغفرين بالأسحار هم\nالذين يشهدون الصبح في جماعة، وذلك داخل في عموم الآية،\n⟦2:463⟧\nفإن شاهد الصبح في جماعة يستحق الصبح.\nقال عز وجل: (شهد الله أنه لا إله إلا هو والملائكة وأولو العلم قائما بالقسط لا إله إلا هو العزيز الحكيم (18)\nالشاهد بالشيء يقتضي حضوره بعلمه، والإنباء عنه، والحكم بما عليه.\nولهذا تفسر الشهادة تارة بالحضور، وتارة بالعلم.\nوتارة بالإعلام، وتارة بالحكم.\nإن قيل: ما وجه قوله: ﴿شَهِدَ ٱللَّهُ﴾⟪3:18⟫ وقوله: ﴿لَّٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ﴾⟪4:166⟫، وشهادة المدعي بما يدعيه لا تقتضي زيادة على دعواه.\nمع أن هذه الشهادة\n⟦2:464⟧\nإن كانت للجاحدين فغير مقبولة، وإن كانت للمؤمنين به ففضلة؟\nوهل يكفي النبي - صلى الله عليه وسلم - إذا طولب بالدلالة أن يقول: الله شاهد لي بذلك؟\nقيل: الشاهد العالم بالشيء، المبين لغيره، وأصدق شاهد\nمن يعلم المشهود عند الدلالة المنبئة عن صدقه، وعن كون الأمر\nعلى ما شهد به، والبارئ عز وجل لما جعل في كل شيء تنبؤا عن\nوحدانيته صار له في كل شيء لسان يشهد أنه واحد، وهذا ظاهر،\n⟦2:465⟧\nوبين بقوله: ﴿وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ﴾⟪3:18⟫ أنهم قد عرفوا ذلك\nوينبئون عنه، فإن الأدلة التي يذكرها العلماء، وتأتي بها الملائكة\nوالأنبياء شهادة منهم، فحثهم الله تعالى بهذا القول على التأمل.\nليعرفوا صحة ما شهدوه، وكذا الآية كأنه أقال، لنبيه:\nلا تستوحش من تكذيب الكافرين لك، فقد أبدى الله عز وجل\nمن الآيات ما ينبئ أنه تعالى شاهد لك بصدق دعواك."}, {"a": [18], "v": 2, "p": 465, "ev": 2, "ep": 467, "sid": 667, "t": "وقوله: ﴿قَآئِمَۢا بِٱلۡقِسۡطِۚ﴾⟪3:18⟫ أي هو تعالى مراع للعدالة بكل حال، وذلك\nحال مؤكدة.\n⟦2:466⟧\nفإن قيل: ما وجه تكرير ﴿لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪3:18⟫ في الآية؟\nقيل: لما كان منتهى إدراك الإنسان للبارئ تعالى أن يعرف الموجودات.\nفيعلم أنه ليس إياها ولا مشبها بشيء منها، صار صفات التنزيه\nله أشرف من صفات التمجيد له، إذ كان عامة صفات التمجيد\nفي ألفاظها مشاركة، يصح وصف العباد بها، ولأجل ذلك\nعظم ما ورد من صفاته على لفظ النفي، نحو: ﴿لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ﴾⟪2:255⟫\n⟦2:467⟧\nقيل في سورة الإخلاص: \"إنها تعدل ثلث القرآن \"، لكونها تنزيها محضا، فإن لفظي: الأحد والصمد وإن كانا على صورة الإثبات - فنفي للتثنية والتشبيه)، ثم أبلغ ما يوصف به من التنزيه: ﴿لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪3:18⟫ فتكريره هاهنا\nلأمرين: أحدهما: لكون الثاني قطعا للحكم، كقولك: أشهد\nأن زيدا خارج وهو خارج.\nوالثاني: لئلا يسبق بذكر العزيز الحكيم إلى قلب السامع تشبيه، إذ قد يوصف بهما المخلوق."}, {"a": [19], "v": 2, "p": 468, "ev": 2, "ep": 470, "sid": 670, "t": "قوله عز وجل: (إن الدين عند الله الإسلام وما اختلف الذين أوتوا الكتاب إلا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بآيات الله فإن الله سريع الحساب (19)\nقد تقدم وجوه الدين، وأن للإسلام ثلاث منازل:\nالأول: الاعتراف الذي يحقن الدم.\nوالثاني: أن يكون مع الاعتراف اعتقاد صحيح ووفاء بالفعل.\nوالثالث: أن يكون مع ذلك استسلام فيما يجري عليه من\n⟦2:469⟧\nقضاء ألله، وهو المسؤول بقوله عز وجل: ﴿تَوَفَّنِي مُسۡلِمٗا﴾⟪12:101⟫\nوغاية الإنسان في ذلك أن يكون كإبراهيم حين قيل له: أسلم.\n﴿قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾⟪2:131⟫ بين تعالى أن حقيقة طاعة الإنسان\nبحسب ما يكون منه من الاستسلام في المنازل الثلاث، وقد\nقرئ (أن الدين) بالفتح، فيصح أن يكون بدلا من الأول.\nواستغني عن الضمير الراجع إلى الله لإعادة ذكره، ويجوز أن\nيتعلق بفعل مضمر دل عليه الأول، ومن قرأ ﴿شَهِدَ ٱللَّهُ أَنَّهُۥ﴾⟪3:18⟫\n⟦2:470⟧\nفشهد يعمل في قوله ﴿إِنَّ ٱلدِّينَ﴾⟪3:19⟫ وإنه كالعلة.\nوقوله: ﴿وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪3:19⟫ كقوله: ﴿إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ﴾⟪2:213⟫ والكلام فيه قد تقدم."}, {"a": [20], "v": 2, "p": 470, "ev": 2, "ep": 474, "sid": 672, "t": "قوله عز وجل: (فإن حاجوك فقل أسلمت وجهي لله ومن اتبعن وقل للذين أوتوا الكتاب والأميين أأسلمتم فإن أسلموا فقد اهتدوا وإن تولوا فإنما عليك البلاغ والله بصير بالعباد (20).\n⟦2:471⟧\nالوجه: العضو المعروف، وعبر به عن الجملة.\nوقيل: هو القصد، نحو وجهي إلى فلان.\nوالذين أوتوا الكتاب: قيل هو عام فيمن نزل إليهم الكتاب.\nوالأميون من سواهم من اليهود ومن النصارى ومن العرب.\nإن قيل: كيف يصح\n⟦2:472⟧\nالاقتصار في المحاجة على أن يقول: تقبل ما أقوله أم ترده، فإن\nرددته أعرضت عنك؟\nقيل: المحاجة ضربان: ضرب للاستهداء\nوضرب للعناد.\nولما كان الله قد بين لهم الأدلة، وبين أنهم يعرفونه كما يعرفون أبناءهم.\nقال حينئذ: إن عاندوك فعرفهم مخالفتك لهم.\nوهذا كما يقال لمن أوضحت له الحجة:\nإن قبلت وإلا أعرضنا عنك.\nوقال بعضعهم: إنما نبه بهذه الآية على الحجة اللازمة لهم.\nووجه ذلك أنه قال: قل لهم: إني توجهت إلى الله بعبادة.\nفهل تنكرون كونه معبودا، فإنه لا يمكنهم إنكار\nذلك إذ كان وجوب عبادته والتوحد له محمودا عند الكل، وإنما\nاختلافهم في غيره، فبين أنهم إن أسلموا للحجة فقد اهتدوا، فإن\n⟦2:473⟧\nحجتك لازمة - وليس لهم ما يدعونه حجة، وفي ذلك اهتداؤهم.\n(وإن تولوا) أي إن أبوا أن ينقادوا للحجة فليس عليك إلا البلاغ.\nكقولك: ليس عليك هداهم ونحوه، وقدم الذين أوتوا\nالكتاب، لأن الحجة تلزمهم من وجهين:\nمن الوجه الذي يلزم الأميين، ومن وجه أنهم يدعون الإيمان بإبراهيم وغيره.\nوعلى هذا قال إبراهيم: (يا قوم إني بريء مما تشركون (78) إني وجهت وجهي للذي فطر السماوات والأرض حنيفا)\n⟦2:474⟧\nوقوله: ﴿وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ﴾⟪3:20⟫: أي عارف بمقاصدهم.\nوقوله: ﴿وَمَنِ ٱتَّبَعَنِۗ﴾⟪3:20⟫ معطوف على التاء أي، (أسلمت).\nولم يحتج إلى تأكيد الضمير، كما أكد في قولهم: خرجت أنا وزيد.\nللفصل القائم مقام التأكيد، وحذف الياء من قوله.\n(اتبعن) لدلالة الكسر عليه."}, {"a": [21], "v": 2, "p": 475, "ev": 2, "ep": 478, "sid": 677, "t": "قوله عز وجل: (إن الذين يكفرون بآيات الله ويقتلون النبيين بغير حق ويقتلون الذين يأمرون بالقسط من الناس فبشرهم بعذاب أليم (21)\nهذا تعريض ببني إسرائيل، وذاك لأن أبا عبيدة بن الجراح قال:\nقلت: يا رسول الله، من أشد الناس عذابا يوم القيامة؟\nقال: \"من قتل نبيا أو رجلا أمر بمعروف ونهى عن منكر\"، ثم قرأ الآية، وقال: \"يا أبا عبيدة قتل بنو إسرائيل ثلاثة وأربعين نبيا في ساعة من صدر النهار، فقام مائة واثنا عشر رجلا من عبادهم، فأمروهم بالمعروف، ونهوهم عن المنكر، فقتلوا جميعهم آخر النهار\".\n⟦2:476⟧\nإن قيل: لم أعيد يقتلون ولم يقل: ويقتلون النبيين ويقتلون الذين\nيأمرون؟ فقل: لأمرين:\nأحدهما تفظيعا لشانهم.\nوالثاني: أنه يجوز أن يكون أحد القتلين تفويت الروح والآخر الإهانة وإماتة\nالذكر، وذلك كثير في كلامهم.\nإن قيل: لم قال: ﴿وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ﴾⟪3:21⟫، وقتلهم لا يكون بحق على وجه حتى يحتاج إلى تقييده بذلك؟\nقيل: قوله ﴿بِغَيۡرِ حَقّٖ﴾⟪3:21⟫ ليس يتعلق بقوله ﴿وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ﴾⟪3:21⟫، بل هو من صفة الذين يكفرون، كأنه قال: هم يقتلون، وهم غير محقين، ووصفهم بذلك من أنهم\n⟦2:477⟧\nغير محقين في جميع أحوالهم، وتخصيص أنها للاستقبال في\nقوله: ﴿وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ﴾⟪3:21⟫ كتخصيصه في قوله: ﴿تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ﴾⟪2:91⟫، قد تقدم الكلام فيه.\nوكذلك قد تقدم تخصيص لفظ البشارة في العذاب.\nمع كونه موضوعا لما يسر.\n⟦2:478⟧\nفإن قيل: ما فائدة قوله ﴿مِنَ ٱلنَّاسِ﴾⟪3:21⟫؟\nقيل: عنى بذلك وجود الفضيلة المختصة بالإنسان في النبيين، والآمرين\nبالقسط، وذلك نحو قولهم: فلان هو إنسان، وعلى ذلك\nقول الشاعر:\nإذ الناس ناس والزمان يعز به."}, {"a": [22], "v": 2, "p": 479, "ev": 2, "ep": 480, "sid": 681, "t": "قوله عز وجل: (أولئك الذين حبطت أعمالهم في الدنيا والآخرة وما لهم من ناصرين (22)\nالحبوط: فساد العمل، وأصله من الحبط، أي فساد بطون الماشية من مأكل الربيع، ولذلك قال عليه الصلاة والسلام: \"إن مما ينبت الربيع ما يقتل\nحبطا أو يلم\".\nيعني بقوله (أولئك): هم الذين يكفرون ويقتلون.\n⟦2:480⟧\nبطلت في الدنيا والآخرة أعمالهم، أما في الدنيا فلأنهم لم يحصلوا\nمنها محمدة، وأما في الآخرة فلم يحصلوا منها مثوبة، وذلك، نحو\nقوله تعالى : ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫.\nإن قيل: لم قال: ﴿وَمَا لَهُم مِّن نَّٰصِرِينَ﴾⟪3:22⟫ ولو قال: ما لهم\nمن ناصر كان ذلك عاما لكونه نكرة منفية؟\nقيل: لما كان القصد بهذه الآيات تثبيت الوحدانية ونفي الكثرات، نبه بلفظ الجمع على أن ناصر الناس واحد، فكأنه قال: ما للناس ناصرون، بل لهم\nناصر واحد، فيجب أن يطلب مرضاته ويتحرى مرسوماته.\nوذلك نحو قوله: ﴿هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم﴾⟪35:3⟫ و ﴿مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ﴾⟪28:71⟫، وما أشبه ذلك من الآيات."}, {"a": [23], "v": 2, "p": 481, "ev": 2, "ep": 484, "sid": 683, "t": "قوله عز وجل: (ألم تر إلى الذين أوتوا نصيبا من الكتاب يدعون إلى كتاب الله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون (23)\nالحكم: القضية التي تردع المبطل، ومنه حكمة اللجام.\nوالآية تتناول أليهود والنصارى وإن كانت واردة في اليهود.\nقال ابن عباس: إن رسول الله - صلى الله عليه وسلم - رأى جماعة من اليهود فدعاهم، فقالوا: على أي ملة أنت يا محمد؟\nقال: \"على ملة إبراهيم\" فقالوا: إن إبراهيم كان يهوديا.\nفأنزل الله تعالى هذه الآية، وقيل: كان ذلك\nفي سبب اليهوديين اللذين رجمهما النبي - صلى الله عليه وسلم -، وقالت اليهود: إن ذلك ليس في التوراة، فأكذبهم النبي - صلى الله عليه وسلم -، ودعا بالتوراة، فقرأ منها آية الرجم، وقيل: كان في سبب نبوته وتكذيبهم\n⟦2:482⟧\nإياه، وقوله: ﴿ٱلَّذِينَ أُوتُواْ﴾⟪3:23⟫ وإن كان لفظه عافا فمعناه\nخاص، لأنه ليس كلهم فعلوا ذلك، ألا ترى إلى قوله: ﴿مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ﴾⟪3:113⟫.\nإن قيل: لم قال: ﴿مِّنَ ٱلۡكِتَٰبِ﴾⟪3:23⟫، ثم قال: ﴿كِتَٰبِ ٱللَّهِ﴾⟪3:23⟫.\nوهل الأول هو الثاني أم غيره؟\nقيل: قد قال بعضهم: الأول والثاني\n⟦2:483⟧\nواحد، وهما التوراة، لقوله تعالى: ﴿قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ﴾⟪3:93⟫\nالآية، وذكرها باللفظين تعظيما لها، وقيل: عنى بالأول\nالتوراة، وبالثاني القرآن وغيره من كتبه، تنبيها أن كل كتاب\nيقضي بصحة ما هو فيه.\nوقيل: عنى بالذين أوتوا الكتاب: الذين أعطوا حظا من المعرفة\nبكتاب الله، أي كتاب كان من كتبه.\nإن قيل: هل بين التولي\n⟦2:484⟧\nوالإعراض فرق؟\nوهل المعرضون هم المتولون أم غيرهم؟\nقيل: تولي الشيء أن تليه، فإذا عدي بعن صار لترك ذلك.\nوالإعراض في الأصل أن تجعل عرضك إليه، أي جانبك.\nومنه قيل: أعرض لك الصيد فارمه فيجوز أن يعني بالتولي\nتولي فريق من الذين أوتوا نصيبا من الكتاب، وبالإعراض\nجماعتهم، ويجوز أن يكون التولي والإعراض جميعا\nللفريق، فيكون معنى التولي عنه ترك موالاته.\nوالإعراض يكون بالبدن، وذلك لئلا يحتج عليهم إذا حضروا\nفيلزمهم حجة.\nوعلى ذلك قوله: ﴿وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ﴾⟪24:48⟫."}, {"a": [24], "v": 2, "p": 485, "ev": 2, "ep": 487, "sid": 687, "t": "قوله عز وجل: (ذلك بأنهم قالوا لن تمسنا النار إلا أياما معدودات وغرهم في دينهم ما كانوا يفترون (24)\nقد تقدم الكلام فيما حكي عن أهل الكتاب بقولهم: ﴿لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ﴾⟪2:80⟫\nوالذي غزهم ما حكى عنهم من قوله عز وجل: ﴿نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾⟪5:18⟫ والغر: الأثر الظاهر من\n⟦2:486⟧\nالشيء، ومنه الغرة، والغرار حد السيف اعتبارا بالأثر، ولهذا\nسمى أثره السيف، وغر الثوب أثر كسره، يقال: اطو على\nغرة، واستعير للخديعة، فقيل: غزه واغتره كقولهم: طواه إذا\nخدعه، وسمي الدنيا والشيطان غرورا، لكونهما غارين للإنسان.\nوالغر المغرور، والغرر الخطر المتقدم، كأنه الذي به يغتر، وأما غر\nالطائر الفرخ فاستعارة من الصوت الذي يكون منه عند زقه.\nوالغرغرة: ترديد الصوت من الحلق، فجعل لفظه مرددا على\n⟦2:487⟧\nسبيل الحكاية، كحكاية كثير من الأصوات.\nوالفري: قطع الأديم، واستعير للكذب، استعارة الخلق\nوالاختلاق له.\nإن قيل: هل علموا أنهم كاذبون فيما يقولون؟\nقيل: إما أنهم علموا واغتروا برئاستهم وأعراضهم الدنيوية، أو تمكنوا من\nعلمه فلم يتحروه اغترارا بما هم بصدده، وعلى كلا الوجهين\nيستحقون الذم."}, {"a": [25], "v": 2, "p": 487, "ev": 2, "ep": 488, "sid": 689, "t": "قوله عؤ وجل: (فكيف إذا جمعناهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون (25)\nما سئل عنه بكيف محذوف، كأنه قيل: كيف حالهم أو قولهم وافتراؤهم.\nفحذف لدلالة الكلام عليه، كحذفه في قوله\n⟦2:488⟧\n﴿فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ﴾⟪47:27⟫\nومعناه: كيف حالهم إذا جوزوا بفعلهم، ولم يظلموا في بخس\nما استوجبوا من ثواب، أو زيادة ما استحقوا من عقاب.\nودل بالآية أن الكفار لا تغفر ذنوبهم، وعلي ذلك ﴿يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ﴾⟪5:37⟫ الآية.\nوقد تقدم معنى قوله: ﴿وَوُفِّيَتۡ كُلُّ نَفۡسٖ﴾⟪3:25⟫ في سورة البقرة."}, {"a": [26], "v": 2, "p": 488, "ev": 2, "ep": 498, "sid": 690, "t": "وقوله عز وجل: (قل اللهم مالك الملك تؤتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير إنك على كل شيء قدير (26)\nاللهم: تقديره عند سيبويه يا الله،\n⟦2:489⟧\nوالميمان بدل من ياء، ولا يستعمل ذلك إلا في هذه اللفظة فقط.\nوعند الفراء تقديره: يا الله امنا بخير، فجعلا بمنزلة لفظ\nواحد، وحذف الهمزة منه، كقولهم: هلم، وأصله: هل أم،\n⟦2:490⟧\nوقال البصريون: لو كان كما ذكر الفراء لاستغنى به عن جواب\nالشرط. إذا قيل: يا الله امنا بخير. لكون ذلك مكررا.\nوالنزع: جذب الشيء من الشيء، وفصله عنه، ومنه المنازعة.\nوسمى الشوق نزاعا ونزوعا لما تصور في ذلك أن المحبوب ينزع\nقلب المحب منه، والنزع ضربان: نزع إلى الشيء وهو الاشتياق.\nونزع عنه، وهو الكف، وقيل للغريب: نزيع، لكونه منزوعا\nعن مسقط رأسه، أو لكونه نازعا إليه، أي مشتاقا، وقيل لمن\nيشبه أعمامه وأخواله: نزيع لنزع الشبه منهم، أو لكونه منزوعا\nبالشبه عنهم، وسمي السهم منزعا.\nوالنزعة: الموضع من رأس الأقرع، لكون شعره نزيعا عنه.\nوقد تقدم الكلام في الملك،\n⟦2:491⟧\nوالملك وأن الملك كالنوع للملك، فإن كل ملك ملك ما.\nوليس كل ملك ملكا، وقد عظم الله أمره، وقرن بالكتاب والنبوة\nذكره، ففال: ﴿أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا﴾⟪4:54⟫.\nوقال: ﴿إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا﴾⟪5:20⟫\nوقيل: الدين أس والملك حارس، لكون أحدهما غير مستغن عن الآخر من وجه، وقد يسمى المتسلط ملكا وإن كان على ضرب من المجاز، وعلى هذا\nقوله: ﴿وَكَانَ وَرَآءَهُم مَّلِكٞ﴾⟪18:79⟫، فسماه ملكا مع كونه غاصبا.\n⟦2:492⟧\nواختلف: هل يؤتى الملك الفاسق والكافر؟\nفمنهم من قال : لا يؤتاهما.\nوإليه ذهب البلخي والجبائي، وذلك لنظرهم\nإلى الملك الأول، ولاعتبار قوله ﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾⟪2:124⟫.\nومنهم من قال: يؤتاهما ذلك، وذلك لنظرهم إلى الثاني الذي هو\nالتسلط، وكون ذلك أحد الأغراض الدنيوية، ولهذا قال\n⟦2:493⟧\nربنا: ﴿إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا﴾⟪10:88⟫، والأظهر\nفي الآية أنه يعني الملك، الحقيقى لقوله: ﴿وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ﴾⟪2:247⟫\nفأضافه إلى نفسه تعظيما له\nوالملك المطلق هو الملك الإلهي، الذي لا جور فيه بوجه، ولذلك قرنه\nبالعز والذل، وإخراج الحي من الميت، والميت من الحي، وإيلاج\nالليل في النهار، والنهار في الليل، وإعطاء الرزق، ونبه بقوله:\n﴿مَٰلِكَ ٱلۡمُلۡكِ﴾⟪3:26⟫ أن الملك في الحقيقة له وما لغيره عارية مستردة.\nولم يعن بالملك هاهنا سياسة العامة فقط، بل ملك الإنسان\nعلى قواه وهواه، فقد قيل: لا يصلح لسياسة الناس من لا يصلح\n⟦2:494⟧\nلسياسة نفسه. وقيل لبعضهم: من الملك؟ فقال: من ملك هواه\nفقهره، وقوله: ﴿وَتُعِزُّ مَن تَشَآءُ﴾⟪3:26⟫ أي تعزه بإعطائه الملك.\n﴿وَتُذِلُّ مَن تَشَآءُۖ﴾⟪3:26⟫ باسترجاعه منه أو حرمانه إياه.\nوقيل: تعز من تشاء بأن تصونه عن تمكينه من الملك في الدنيا.\nوتذل من تشاء بإعطائه ذلك، وهذا التفسير على النظر إلى ما قال عليه\nالصلاة والسلام: \"ستحرصون على الإمارة، ثم تكون حسرة\nوندامة إلى يوم القيامة\"\nوما قال أبو بكر رضي الله عنه:\n⟦2:495⟧\n\"إن أشقى الناس في الدنيا والآخرة الملوك، إن الرجل إذا ملك\nزهده الله فيما في يده، ورغبه فيما في يد غيره، ونقصه شطر أجله\nوأشرب قلبه الإشفاق، فهو يحسد على القليل، ويتسخط\nالكثير، فإذا وجبت نفسه حاسبه الله فأشد حسابه وأقل غفره \"\nوقال بعض المفسرين: أمر نبيه في هذه الآية أن يدعوه، بأن يحول\nعز فارس إلى العرب، وخضص الملك بالنبوة، فقال معناه:\nتؤتي النبوة من تشاء وتصرفها عمن تشاء.\nوقيل قوله: ﴿وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ﴾⟪3:26⟫\n⟦2:496⟧\nليس براجع إلى الملك، وإنما معناه:\nمن يشاء بطاعته، ويذل من يشاء بمعصيته، والأظهر أن يكون\nذلك عاما في كل عز وذل دنيويا كان أو أخرويا.\nإن قيل: كيف قال: ﴿بِيَدِكَ ٱلۡخَيۡرُۖ﴾⟪3:26⟫ والخير والشر بيده؟\nفقيل في ذلك أجوبة:\nالأول: أراد الخير والشر، لكن الآية لما كانت في الحمد\nوالشكر لا للحكم ذكر الخير، إذ هو المشكور عليه، وعلى ذلك -\n⟦2:497⟧\nقوله ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾⟪26:80⟫، وفيه تعليمنا كيف نمدح\nأبناء جنسنا بأن نذكرأشرف خصالهم.\nوالثاني: أنه نص على المعظم ليفهم منه الضد الآخر.\nكقوله: ﴿سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ﴾⟪16:81⟫، وكقول الشاعر:\nفما أدري إذا يممت وجها. . . أريد الخير أيهما يليني\nوالثالث: أنه أراد بالخير: الخير والشر، وسماهما خيرا، لأنه\nليس في العالم شر خالص، كما أن فيه خيرا خالصا، وذاك أن ما\nهو شر بكذا هو خير لكذا، فالخير والشر يصدق عليهما الوصف\nبالخير من هذه الجهة، ولا يصدق عليهما الوصف بالشر، فلو\nقال بيده الشر، لم يدخل فيه الخير.\nووصفه بالقدرة على كل\n⟦2:498⟧\nشيء في آخر الآية تنبيه على أنه أراد الأمرين، فإن سعة القدرة\nتقتضيهما."}, {"a": [27], "v": 2, "p": 498, "ev": 2, "ep": 501, "sid": 700, "t": "قوله عز وجل: (تولج الليل في النهار وتولج النهار في الليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب (27).\nالولوج: الدخول في مضيق، فهو أخص من الدخول.\nيقال: تولج الظبي، والولجة: بناء بين يدي فناء القوم، كالمدخل\nإليه. واستعير الوليجة لبطانة الرجل كالدخيل وإيلاج\n⟦2:499⟧\nالليل في النهار والنهار في الليل، يتناول تعاقب أحدهما الآخر.\nوالزيادة من كل واحد منهما في الآخر، وقد فسر بهما.\nوقوله: ﴿وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ﴾⟪3:27⟫\nيتناول خروج الإنسان من النطفة، نحو: ﴿أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةٖ﴾⟪36:77⟫، وقوله: ﴿وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرٗا﴾⟪25:54⟫، وهذا هو\n⟦2:500⟧\nالذي قال الضحاك والسدي وابن زيد: الدجاجة من\n⟦2:501⟧\nالبيض، والبيض من الدجاج ..\nوقال الحسن: عنى إخراج المؤمن من الكافر والكافر من المؤمن.\nوقال بعضهم: يتناول ذلك كل شيء من الأركان.\nإذا استحال إلى غيره.\nولهذا قال السدي: يخرج النخلة من النواة، والنواة من النخلة.\nوالأظهر في قوله: الحي من الميت. تصور اثنين.\nوقد قيل: عنى بذلك شيئا واحدا تتغير به الحال.\nفيكون ميتا ثم يحيا، وحيا فيموت، كقولك: جاء من فلان أسد.\nوليس الأسد إلا هو، وقد تقدم الكلام في قوله ﴿بِغَيۡرِ حِسَابٖ﴾⟪3:27⟫."}, {"a": [28], "v": 2, "p": 502, "ev": 2, "ep": 513, "sid": 704, "t": "قوله عز وجل: (لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء إلا أن تتقوا منهم تقاة ويحذركم الله نفسه وإلى الله المصير (28).\nقد عظم الله موالاة الكافرين وموادتهم والركون إليهم في آيات\nكقوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ﴾⟪5:51⟫\nوقال: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ﴾⟪60:1⟫\nوقال: ﴿لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ﴾⟪58:22⟫ وقال: ﴿لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ﴾⟪3:118⟫.\nوقال: ﴿وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ﴾⟪11:113⟫\nوأمرنا بالإعراض عنهم.\nفقال: ﴿فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا﴾⟪53:29⟫\nوقال عليه الصلاة والسلام:\n⟦2:503⟧\n\"لاتراءى ناراهما \" وقال: \"أنا بريء من كل مسلم مع مشرك \"\nإن قيل: ما وجه جواز مواصلتهم والاستعانة بهم واتخاذهم\nعبيدا، وذلك ضرب من الموالاة، فالجواب من أوجه:\nالأول: أن هذه الآيات تقتضي المنع أمن، موالاتهم، إلا ما\nخص، وفسح لنا فيه.\n⟦2:504⟧\nوالثاني: أن الموالاة المطلقة هي أن تواليهم في جميع الأمور.\nفأما في شيء دون شيء فليس ذلك بموالاة.\nالثالث: أن يكون ذلك مخصوصا في الموالاة الدينية.\nالرابع: أن الموالاة على ضربين: موالاة الأرفع للأوضع، وذلك\n⟦2:505⟧\nباستخدامه إياه ورعايته والحماية عليه، وموالاة الأوضع للأرفع\nوذلك بالخدمة. والذي نهي عنه المسلم جزما هو أن يوالي الكافر\nموالاة الأوضع للأرفع بالخدمة له والاستعانة به استعانة الذليل\nبالعزيز، لا أن يستعين به استعانة العزيز بالذليل والمخدوم\nبالخادم، فذلك مرخص فيه، وذاك لما قال النبي - صلى الله عليه وسلم -: \"الإسلام يعلو ولا يعلى\" ومن هذا رخص أن ننكح منهم دون أن ينكحوا\n⟦2:506⟧\nفينا، وأن نملك أرقاءهم ولا يملكوا أرقاءنا، وأن نرثهم\nفي قول من يرى ذلك، ولا يرثونا بوجه، ثم قد يكره لمن لم\n⟦2:507⟧\nيقر في الإسلام المصاهرة إليهم، والاستعانة في المهن بهم\nتفاديا أن يغروه، وذلك ما قال عليه الصلاة \"والسلام لحذيفة\nلما تزوج بمشركة: \"دعها فإنها لا تحصنك\"، بل\n⟦2:508⟧\nلذلك قال: \"مثل الجليس الصالح كمثل الداري إن لا يحذك\nمن عطره تعلقك من ريحه، ومثل الجليس السوء كمثل القين إن\nلا يحرقك بشرره يؤذك بدخانه \"، وقال بعض الحكماء:\n⟦2:509⟧\n\"إياك ومجالسة الشرير، فإن طبعك يسرق من طبعه، وأنت لا تدري \".\nوقوله: ﴿وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ﴾⟪3:28⟫\nإياس من الموالاة التي أثبتها بقوله: ﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ﴾⟪2:257⟫\nونحوه، وقوله: ﴿إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ﴾⟪3:28⟫ فرخصه في إظهار\nالموالاة باللسان دون القلب، حيث يحصل تقية، كقوله: ﴿إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ﴾⟪16:106⟫\nولاحرج في مداراة الكافر حيث يخاف شره، أو يرجى صلاحه، فقد روي عن النبي - صلى الله عليه وسلم -\n⟦2:510⟧\nأنه استأذن عليه بعض الناس، فقال: \"بئس أخو العشيرة\nهو\"، فلما دخل أكرمه، وسألته عائشة بعد خروجه، فقال: \"إن شر\nالناس من يكرم اتقاء لسانه\".\nواختلف هل يجوز الإفصاح بالحق في حال التقية؟\nفأجاز ذلك بعضهم استدلالا بما روى الحسن: أن مسيلمة الكذاب أخذ رجلين من أصحاب رسول الله - صلى الله عليه وسلم -\n⟦2:511⟧\nفقال لأحدهما: أتشهد أني رسول الله؟ قال: نعم.\nفخلاه، ثم دعا الآخر، فقال له ذلك، فأبى أن يقوله فقتله، فقيل\nذلك للنبي - صلى الله عليه وسلم -، فقال: \"أما المقتول فمضى على صدقه ويقينه، وأخذ بفضيلة، فهنيئا له.\nوأما الآخر فأخذ برخصة الله، فلا تبعة عليه \"\nوجملة الأمر أن الإفصاح عند التقية إيفاء بالحق، مستحسن حيث كان فيه نفع ديني، فأما إذا لم يكن في ذلك نفع ديني بوجه، فالعدول إلى كلمة الكفر على وجه التعريض أولى،\n⟦2:512⟧\nإن قيل: ما تعلق هذه الآية بما قبلها؟\nقيل: لما عرفنا أنه مالك الكل والقادر عليه نهانا عن موالاة من يعاديه.\nوقوله: ﴿وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ﴾⟪3:28⟫ فالحذر: الاحتراز من السطوة.\nوذلك على ضربين: أحدهما: حذر الإنسان إياه برؤية ذنوبه.\nوإليه قصد بقو له: (يحذر الآخرة)، والثاني: حذره برؤية\nتقصيره في طاعته، وإياه قصد بهذه الآية، وعلى هذا ذكر التقوى.\nفقال في موضع: ﴿وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ﴾⟪2:281⟫.\nوفي موضع: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ﴾.\nقال الحسن: من رحمته أن\n⟦2:513⟧\nحذرهم نفسه، ولتحذيره إياهم قال: ﴿وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ﴾\nفإنه حذرنا، بخلاف ما بفعل الماكر، وإلى مقتضى معناه أشار العرب\nبقول: أعذر من أنذر، وفائدة قوله: ﴿وَيُحَذِّرُكُمُ ٱللَّهُ﴾⟪3:28⟫ في\nهذا المكان أنه لما ذكر قوله: ﴿إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ﴾⟪3:28⟫ بين أنكم وإن\nاتقيتموهم فاحذروا الله، فإنه يحذركم أن توالوهم بقلوبكم."}, {"a": [29], "v": 2, "p": 513, "ev": 2, "ep": 515, "sid": 715, "t": "قوله عز وجل: (قل إن تخفوا ما في صدوركم أو تبدوه يعلمه الله ويعلم ما في السماوات وما في الأرض والله على كل شيء قدير (29)\nالأصل في الصدر: الجارحة، فاستعير لصدر المجلس والكتاب\nوالكلام، وصدره إذا أصاب صدره، أو قصد نحو ظهره، وكتفه.\nوإذا عدي بعن اقتضى الانصراف عنه، والصدر يقال للمصدر\nاللفظي ولموضع الصدر، ولزمانه، والصدار الصدرة يغطى\n⟦2:514⟧\nبها الصدر على بناء الدثار واللباس، ويقال له الصدرة، ولا\nنهى تعالى عن موالاة الكفار - وذلك يكون بالقلب قبل أن يكون\nبالجوارح - حذرهم أن يوالوهم بقلوبهم، فيكونوا كمن وصفهم\nبقوله: ﴿وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ﴾⟪4:81⟫، وكمن وصفهم بقوله تعالى: ﴿إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ﴾⟪63:1⟫ الآية، بين أنه لا يخفى عليه ذلك، بل لا يخفى عليه ما في السموات والأرض، وهو قادر عليهم، وإذا كان قادرا وعالما بالسرائر فحق أن يحذر.\nإن قيل: لم قدم الإخفاء على الإبداء، ومن البادي يتوصل\nإلى الخافي، وقضية المتمدح أن يقول فلان لا يفوتني: مشى أو\nعدى ولا يكاد يقال: عدى أو مشى؟ قيل: لما كان العلم يظهر في\nالنفس، ثم يبرز بالقول أو بالكتاب صار الخافي سببا للبادي،\n⟦2:515⟧\nفنبه بذلك أنه يعلم الشيء منا قبل أن نظهره، وأنه يستوي عنده\nالسر والجهر، وعلى هذا قال: ﴿سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ﴾⟪13:10⟫، وقال: ﴿يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ﴾⟪6:3⟫، فقدم الشر في هذا الموضع.\nوقال في موضع: ﴿وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ﴾⟪2:284⟫ فقدم الإبداء تنبيها أنهما عنده سواء."}, {"a": [30], "v": 2, "p": 515, "ev": 2, "ep": 519, "sid": 717, "t": "قوله عز وجل : (يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو أن بينها وبينه أمدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد (30).\nتقديره: يحذركم نفسه يوم تجد، أو اذكر يوم تجد،\n⟦2:516⟧\nأو الله على كل شيء قدير يوم تجد.\nوقوله: ﴿مَّا عَمِلَتۡ مِنۡ خَيۡرٖ﴾⟪3:30⟫ مفعول تجد، ﴿وَمَا عَمِلَتۡ مِن سُوٓءٖ﴾⟪3:30⟫ معطوف عليه، كأنه قيل: وما عملت من سوء محضرا، وتوفى: في موضع\nالحال، وقيل: و ﴿وَمَا عَمِلَتۡ مِن سُوٓءٖ﴾⟪3:30⟫ استئناف، إما جزاء\nو (تود) جوابه، وعلى هذا لو قرى (تود) بالفتح أو بالكسر\nلجاز، وإما أن يكون بمعنى الذي متضمنا لمعنى الشرط،\n⟦2:517⟧\nوإن لم يكن في تقدير الجزم، نحو: الذي يأتينى له درهم.\nوالأولى أن يكون معطوفا كما تقدم، ووجود الأنفس ما\nعملت: تصوره لها من حيث لا يخفى عليها، ونحوه مما دل على\nذلك قوله: ﴿إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ﴾⟪45:29⟫\nوقوله: ﴿يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ﴾⟪58:6⟫\nفاستنساخه وإحصاؤه: إذكارهم به حتى يعلموه، فإن من صفة\n⟦2:518⟧\nعلم الإنسان أن تحصل صورة المعلوم في قلبه وثبوت الصورة في\n، القلب أوكد كتابة، ويجوز أن يكون معنى ﴿تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ﴾⟪3:30⟫.\nأي جزاء ما عملت من خير وشر.\nإن قيل: ما فائدة حذف الجزاء في هذا المكان ونحوه من قوله: ﴿ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ﴾، وقوله: ﴿ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ﴾⟪39:24⟫.\nوقوله: (فمن يعمل مثقال ذرة خيرا يره (7) ومن يعمل مثقال ذرة شرا يره (8)؟\nقيل: لما أراد أن ينبه أن الإنسان لا يبخس حظه فيما يفعل من خير، ولا يزاد عليه في جزاء ما يفعل من شر، ذكر نفس الفعل دون الجزاء؛ تنبيها له أن فعله مستوفى بالجزاء، حتى كأنه هو، كقولك: زيد هو أبوه بعينه.\nإذا أريد المبالغة في التشبيه به، وإعادة قوله: ﴿وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ﴾⟪3:30⟫، توكيد\nواستظهار عليهم.\nفإن قيل: وكيف علقه بالرأفة؟\n⟦2:519⟧\nقيل: تنبيها لأمن المحبوب من حبيبه، ولهذا قال النبي عليه\nالصلاة والسلام مخبرا عن الله: \"لا يزال العبد يتقرب إلي\nبالنوافل حتى أحبه، فإذا أحببته كنت سمعه الذي يسمع به.\nوبصره الذي يبصر به \" الخبر."}, {"a": [32], "v": 2, "p": 520, "ev": 2, "ep": 521, "sid": 722, "t": "قوله عز وجل: (قل أطيعوا الله والرسول فإن تولوا فإن الله لا يحب الكافرين (32)\nهذا إلزام \"كالأول، لكنه أعم، لأن طاعته أعم من اتباعه، إذ قد يكون الإنسان مطيعا لغيره، ثم لا يكون متبعا له في أفعاله، وذكر ها هنا الرسول تنبيها أن كل من كان رسولا من جهة فطاعته واجبة، \\ثم قال: ﴿فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ﴾⟪3:32⟫، أي من تولى فقد خرج عن التحبب إليه، ومن لم يتحبب إليه بطاعته فهو لا يحبه بإثابته، والكافر غير متحبب إليه بتوليه عنه، فمحال أن يحبه، فصار تقديره: إنكم إذا كفرتم بالإعراض عنه وعن\n⟦2:521⟧\nرسوله، فإنه لا يحبكم. وفي ذلك إبطال دعواهم، حيث قالوا:\n﴿نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾⟪5:18⟫، وقوله: ﴿لَا يُحِبُّ ٱلۡكَٰفِرِينَ﴾⟪3:32⟫ تنبيه\nأنه ينقطع عنهم توفيقه، وبانقطاع توفيقه عنهم يضلون ويعمهون."}, {"a": [33], "v": 2, "p": 521, "ev": 2, "ep": 525, "sid": 723, "t": "قوله عز وجل: (إن الله اصطفى آدم ونوحا وآل إبراهيم وآل عمران على العالمين (33).\nقد تقدم الكلام في معنى الاصطفاء، وأن ذلك منه تعالى\n⟦2:522⟧\nعلى وجهين: أحدهما: على سبيل الثواب بحسب الاستحقاق.\nوالثاني: على سبيل التفضيل والابتداء بالترشيح، الذي يؤدي إلى\nالعمل المرضي، وذلك على ضربين:\nأحدهما: أن يكون ذلك على سبيل الاجتباء، وهو أن تفيض العناية الإلهية عليه، فيجعله على نهاية الكمال بلا اجتهاد منه، ويجعله سببا لتخريج غيره.\nوذلك للأنبياء ومن داناهم من الأولياء.\nالثاني: على سبيل الاهتداء، وهو أن يوفقه برسله ليتبلغ درجة. فدرجة على سبيل\n⟦2:523⟧\nالاكتساب، حتى يقرب من هؤلاء لتحمل المشاق، وذلك للحكماء\nومن داناهم من المؤمنين، ويقال فيهما الاصطفاء، ولوجود\nهذين الطريقين، قال تعالى: ﴿يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ﴾⟪42:13⟫ وقول الفراء: اصطفاؤهم اختيار دينهم.\nوقول الزجاج والجبائي: اختيارهم للنبوة.\nوقول البلخي: هو تفضيلهم على غيرهم بما أولاهم من الأمور الجليلة.\nكل ذلك\n⟦2:524⟧\nداخل في الاصطفاء، وقد تقدم الكلام في الآل وأنه أخص من\nالأهل، فإن الآل يتناول الأخصاء الذين يجرون من الإنسان\nمجرى ذاته، ولهذا يقال لذات الإنسان ولخصائص عشيرته: الآل.\nولم يتناول آل محمد الكافرين من ذويه، وعنى بالمذكورين\n⟦2:525⟧\nفي هذه الآية جملة من فضلهم في قوله: ﴿إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ﴾⟪4:163⟫ الآية، فذكر اثني عشر نبيا، وسنذكر إذا انتهينا إليه تخصيصهم بالذكر، وكيف رتبوا هذا الترتيب، ومخالفة ذكرهم في الترتيب لأزمنتهم.\nإن قيل: كيف تعلق هذه الآية بما قبلها؟\nقيل: تعلقها بها من وجهين.\nأحدهما: أنه لما أمرهم تعالى باتباع نبينا وهم\nيقرون بوجوب اتباع الذين ذكرهم، بين أن جماعتهم في كونهم\nمتساوين في النبوة سواء، وأن الذي دل على وجوب اتباع\nأهؤلاء يدل على وجوب اتباع، سائرهم.\nوالثاني: أنه نبه أن اصطفاءه تعالى لهؤلاء لكونهم مطيعين له، مستحقين لمحبته\nبذلك."}, {"a": [34], "v": 2, "p": 525, "ev": 2, "ep": 528, "sid": 727, "t": "قوله عز وجل: (ذرية بعضها من بعض والله سميع عليم (34)\nالذرية: قيل: من ذرأ الله الخلق فترك همزه نحو روية وبرية ونبى\n⟦2:526⟧\nوخابية وملك من روأ وأنبأ وخبأ وملأك، وقيل: بل هو من\nذرو الريح، وأصله ذروية، وقيل: هي فعلية من الذر نحو قمرية.\nويقال: ذرية للواحد والجمع، ويقال للأصل والنسل، قال تعالى:\n﴿وَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ﴾⟪36:41⟫ أي إياهم، ويقال للنساء:\nالذراري، قال عليه الصلاة والسلام: \"حجوا بالذراري، ولا تأكلوا مالها وتذروا أرباقها في أعناقها \" أي بالنساء،\n⟦2:527⟧\nفأما الصبيان فلا أرباق في أعناقها؛ إذ لا حج عليهم.\nقوله: ﴿بَعۡضُهَا مِنۢ بَعۡضٖۗ﴾⟪3:34⟫ يعني في الموالاة الدينية، لقوله: ﴿وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ﴾⟪9:71⟫ وقوله: ﴿ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ﴾⟪9:67⟫ وقوله لنوح: ﴿إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ﴾⟪11:46⟫ ردا عليه لما قال في الكناية عن هذا العدو.\nوالضعة: الخساسة، في مقابلة الرفعة، ولذلك استعير\nصعود الجبل وبلوغ السماء ونحو ذلك للرفعة، والوقوع في\nالثرى ونحوه للضعة.\n⟦2:528⟧\nوالرجيم: المرجوم، وأصل الرجم: الرمي بالرجام أي\nالحجارة، وقيل ذلك للنجم المنقض، لقوله: ﴿وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ﴾⟪67:5⟫ وقيل للظن والكلام المقرع: رجم، ومنه (رجما بالغيب).\nفلما وضعتها قالت رب إني وضعتها أنثى والله أعلم بما وضعت وليس الذكر كالأنثى وإني سميتها مريم وإني أعيذها بك وذريتها من الشيطان الرجيم (36)"}, {"a": [35, 36], "v": 2, "p": 528, "ev": 2, "ep": 531, "sid": 730, "t": "وقوله: ﴿فَلَمَّا وَضَعَتۡهَا﴾⟪3:36⟫ أي وضعت حملها، وأنثها على\nالمعنى، وقولها: ﴿إِنِّي وَضَعۡتُهَآ أُنثَىٰ﴾⟪3:36⟫ لكون الأنثى ناقصة\nالعقل والدين، ولهذا قالت: ﴿وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ﴾⟪3:36⟫ ولأنه\n⟦2:529⟧\nروي أنه لم يكن يستصلح للتحرير من قبل إلا الذكور.\nوبين بقوله: ﴿وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ﴾⟪3:36⟫ أن إخبارها بذلك لم\nيكن على سبيل الإعلام، بل على معنى أن الله أعلم بمآلها، وحقيقة\nأحوالها، وذلك يحتمل أن يكون من قولها، وأن يكون من قوله\n⟦2:530⟧\nتعالى، وإذا قرئ (بما وضعت) فإخبار عن قولها على سبيل\nالتوجع، إذ لم يكن ما في بطنها على ما أحبت، وفائدة قوله:\n﴿وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ﴾⟪3:36⟫ قيل: هو أن هذا الاسم في لغتهم اقتضى\nمعنى التحرير، وتضرعت امرأة عمران إلى الله تعالى أن يحفظها\nوذريتها من الشيطان، الذي قال: ﴿وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ﴾⟪15:39⟫ لكون\nالأنثى أطوع له، وروي عن النبي - صلى الله عليه وسلم - أنه قال: \"ما من مولود يولد إلا والشيطان ينال منه طعنة، ولها يستهل الصبي إلا ما\nكان من مريم وابنها، فإنها لما وضعتها قالت: ﴿وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ﴾⟪3:36⟫\n⟦2:531⟧\nفضرب دونها حجاب\".\nونبه بقوله: ﴿إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪3:35⟫ إنك تسمع نذري، وتعلم\nحالي ونيتي، فتقبل مني ما قلت."}, {"a": [37], "v": 2, "p": 531, "ev": 2, "ep": 535, "sid": 733, "t": "قوله في وجل: (فتقبلها ربها بقبول حسن وأنبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يا مريم أنى لك هذا قالت هو من عند الله إن الله يرزق من يشاء بغير حساب (37)\nالقبالة: الكفالة، فقوله: (تقبلها) قيل: تكفل تربيتها،\n⟦2:532⟧\nوقيل: رضيها، ولفظ التقبل يقتضيهما.\nقال الحسن: قبوله إياها أنه صانها عن كل أذى وقبول مصدر قبل، نحو:\nوضوء وطهور، ولما كان تقبل وقبل يتقاربان جمع بين التقبل\nوالقبول، تنبيها أنه جمع من الأمرين التقبل الذي يقتضي الرضا\nوالإثابة، وقيل: القبول من قولهم: فلان عليه قبول.\nإذا أحبه من رآه.\nوقوله: ﴿وَأَنۢبَتَهَا نَبَاتًا﴾⟪3:37⟫ أي رباها تربية حسنة.\nوتقدير الكلام: أنبتها فنبتت نباتا، وروي أن أمها لما وضعتها\n⟦2:533⟧\nلفتها في خرقة وبعثت بها إلى مسجد بيت المقدس فقال:\nزكريا: أنا أحق بها، لأن خالتها تحتي، وقالت الأحبار: لو\nتركت لأحق الناس بها لتركت لأمها التي وضعتها، فاختصموا\nفيها فتقارعوا، فقرعهم زكريا.\nواختلف الرزق، فقيل: إنه كان يوجد عندها طعام الشتاء في الصيف، وطعام الصيف في الشتاء، من غير أن كان يدخل إليها آدمي.\nوقال الجبائي: يجوز أن كان\n⟦2:534⟧\nرزقا يأتيها به غير زكريا من حيث لا يعلمه، ولو كان الأمر\nعلى ما ذكر لما أعاد الله ذكره تعجبا من أمرها.\nوقوله: ﴿مِنۡ عِندِ ٱللَّهِۖ﴾⟪3:37⟫ يدل على أنه ليس كما ذكر.\nوقال بعضهم: كان ذلك فيضا من الله يأتيها من العلم والحكمة من غير تعليم آدمي، فسماه رزقا، وهذا أعجب من إتيانها الطعام في غير أنه، لمن عرف\nفضيلة العلم، واللفظ محتمل، ثم بين تعالى أن ذلك ليس\n⟦2:535⟧\nبعجيب، فرزق الله للعباد على وجوه تقصر عنها معرفة الناس."}, {"a": [38], "v": 2, "p": 535, "ev": 2, "ep": 536, "sid": 737, "t": "قوله عز وجل: (هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء (38)\nهنالك: يقع على الزمان والمكان، وإن كان المكان أملك له، يقال: هنا، وهناك، وهنالك، كقولك: ذا، وذاك، وذلك، ولما رأى زكريا من أحوال مريم تلك العجائب، وكان به حاجة إلى الولد مع كبر سنه ووهن من\nعظامه، سأله أن يهب له ذرية طيبة، أي صالحة، واستعمال الطيب\nفي الصالح: كاستعمال الخبيث في ضده، في نحو قوله: ﴿ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ﴾⟪24:26⟫، على أن في الطيب زيادة معنى على الصالح وقوله:\n⟦2:536⟧\n(من لدنك) أي من نعمك وفضلك الإلهي، وذاك أن إيجاد الأشياء\nوإن كانت كلها بقدرته وفضله فعلى ضربين: إبداع، وهو الذي لم\nيجعل لغوه إليه سبيلا، لا للملائكة ولا للناس، وفعل جعل\nللروحاني أو الجسماني إليه سبيلا، فبين بقوله: ﴿مِن لَّدُنكَ﴾⟪3:38⟫ أنه\nيسأل ما يتفرد بإيجاده.\nوقوله: ﴿مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ﴾⟪3:38⟫ أي مجيب\nلمن دعاك على الشرائط التي بها تدعى، وقد تقدم الكلام في\nشرائط الدعاء في قوله: ﴿أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ﴾⟪2:186⟫."}, {"a": [39], "v": 2, "p": 537, "ev": 2, "ep": 543, "sid": 739, "t": "قوله تعالى: (فنادته الملائكة وهو قائم يصلي في المحراب أن الله يبشرك بيحيى مصدقا بكلمة من الله وسيدا وحصورا ونبيا من الصالحين (39)\nالمحراب: قيل: سمي بذلك لأنه موقع محاربة\nالشيطان والهوى، وقيل: لكون الإنسان حريبا من أشغال\nالدنيا.\nوقيل: الأصل فيه أنه موضع حريبة الرجل أي ماله، وذلك أنه\nكان اسما لصدر المجلس، ثم لما اتخذت المساجد سمي به\nمنها ذلك الموضع، وقوله: ﴿بِكَلِمَةٖ مِّنَ ٱللَّهِ﴾⟪3:39⟫ قيل: هي\nكلمة الإيمان، وهو قول قتادة، وقال أبو عبيدة: كتاب الله\n⟦2:538⟧\nوقال غيرهما: عنى به عيسى، وتسمية عيسى بالكلمة\nقيل: لكونه موجدا بكن، المذكور في قوله: ﴿ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ﴾⟪3:59⟫.\nوقيل: سمي بذلك لكلامه في صغره، والسيد\n⟦2:539⟧\nالسايس لسواد الناس، أي معظمهم، ولهذا يقال: سيد العبد.\nولا يقال: سيد الثوب، وقيل: سيدا أي عالما وتقيا وحليما.\nوذلك من شروط السيادة، فمن لم يوجد فيه ذلك فسيادته زور.\nوقال بعض الصوفية: قوله: ﴿وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ﴾⟪3:39⟫\n⟦2:540⟧\nتنبيه أنه قل ما يأتي الإنسان توفيق وفيض إلهي إلا بالالتجاء إليه.\nوالحصور: يقال تارة في معنى الفعول.\nوتارة في معنى الفاعل، فيجوز أن يكون هو الذي حصر نفسه.\nويجوز أن يقال حصره علمه وعقله.\nوقد روي أنه كان ممنوعا من قبل الله تعالى عن النساء.\nوأنه كان معه مثل هدب الملاءة،\n⟦2:541⟧\nوالأول أشبه باستحقاق المدح.\nوقرئ: (نادته)، و (ناداه)، نحو ﴿تَعۡرُجُ ٱلۡمَلَٰٓئِكَةُ﴾⟪70:4⟫ و (يعرج).\nوروي أن عبد الله\n⟦2:542⟧\nذكر الملائكة في كل القرآن.\nوقال أبو عبيدة: وذلك خلاف الكفار، حيث أنثوا الملائكة، وقالوا: بنات الله. وليس تأنيث العرب الملائكة، وتعيير الله إياهم لتأنيث اللفظ، إنما ذلك لجعلهم إياها له بنات، إن قيل: ما معنى ﴿وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ﴾⟪3:39⟫،\n⟦2:543⟧\nوذلك يقتضي جواز نبي ليس بصالح؟!\nقيل: قوله: ﴿مِّنَ ٱلصَّٰلِحِينَ﴾⟪3:39⟫ متعلق بمضمر، أي وهو من الصالحين.\nوذلك مما أكد به قوله: ﴿ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ﴾⟪3:34⟫.\nومعناه من أولاد الصالحين."}, {"a": [40], "v": 2, "p": 543, "ev": 2, "ep": 547, "sid": 745, "t": "قوله عز وجل: (قال رب أنى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر قال كذلك الله يفعل ما يشاء (40)\nالغلام يجوز أن يكون أصلا في بابه، وعنه أخذ الاغتلام، لكون المغتلم شبيها به في المعنى المخصوص، ويجوز أن يجعل الغيلم - وهو منبع الماء - من\nذلك، وسمي الغلام لكونه ذا رونق، ولذلك يقال: فلان عليه\nماء الشباب، والعقر: أصل البنية للدار والإنسان، وعقرته\n⟦2:544⟧\nأي أصبت عقره، أي أصل بنيته، وذلك يقتضي معنى القتل، ثم\nسمي الجرح - أي جرح كان - عقرا، وسمي الخمر عقارا لكونها\nكالعاقر للإنسان.\nوجعل بناؤه بناء الإرواء كالخمار والكباد\nوالمعاقرة: المشاربة، كأنه يطلب كل واحد منهما عقر صاحبه بإسكاره. وامرأة عاقر كأنها تعقر النسل، لإفسادها ماء الفحل.\nوجعل العقر اسما للدية، وكنى به عن بذل البضع.\nوقال ها هنا: (بلغني الكبر) وفي موضع آخر: ﴿وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا﴾⟪19:8⟫، وذاك أنك إذا بلغت الكبر فقد بلغك الكبر،\n⟦2:545⟧\nنحو أدركني الجهد وأدركت الجهد، ولا يقال: أدركني المكان.\nلأن حقيقة إدراك المكان من الإنسان دون المكان، وإدراك الجهد\nوالكبر مجاز في الطرفين، فصار انتساب كل واحد منهما إلى\n⟦2:546⟧\nالآخر سواء، وقوله: ﴿أَنَّىٰ يَكُونُ لِي غُلَٰمٞ﴾⟪3:40⟫ ليس بإنكار لقدرة\nالله، بل لما كانت عادته تعالى في إيجاد الأولاد أن لا يكونوا من\nالهرم والعاقر، أراد التعرف أن ذلك هل يحصل وهما باقيان على\nحالتيهما، أو يكون بإعادة الشباب إليهما، أو يكون ذلك من\nامرأة أخرى أو يحصل ذلك على سبيل لم تجر به العادة؟\nوقال بعضهم: إنما قال أنى يكون لي ذلك؟ استعظاما لنعمة الله.\nكقولك: من لي بكذا؟ ومن أين لي كذا؟\nوقال بعضهم: قال ذلك لأنه لما سمع نداء الملك\nقدر أن ذلك وسوسة من الشيطان، واستبعد بعضهم ذلك.\nوقال: إن الأنبياء لا يشتبه عليهم ما يكون من قبل الملائكة\nبما يكون من قبل الشيطان)،\n⟦2:547⟧\nوقوله: ﴿كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ﴾⟪3:40⟫ على الجواب الأول: أي أنه يهب لك\nالولد وأنت بحالتك، وعلى الثاني: أن نعمته في خلق ذلك\nكنعمته في غيره، وعلى الثالث: إن تعجبت من ذلك فتعجب من\nسائر أفعاله المبدعة، فإن خلقه لذلك كخلقه لما يشاء."}, {"a": [41], "v": 2, "p": 547, "ev": 2, "ep": 551, "sid": 749, "t": "قوله عز وجل: (قال رب اجعل لي آية قال آيتك ألا تكلم الناس ثلاثة أيام إلا رمزا واذكر ربك كثيرا وسبح بالعشي والإبكار (41)\nالعشي: من لدن غروب الشمس إلى انقضاء صدر الليل.\nوخص العشاء بالطعام المتناول فيه، وتعشى تناول\nالعشاء وعشى صار في عشا لظلمة عينه، وآية في وزنها\n⟦2:548⟧\nثلاثة أقوال: الأول: أنها فعلة، وحق مثله أن يجعل لامه معتلا\nنحو: حياة ونواة، ونظيرها راية، والثاني: فعلة إلا أنها قلبت\nكراهية التضعيف، نحو طائي في طيئي، والثالث: فاعلة، وأصلها\nآيية فخففت وذلك ضعيف لقولهم في تصغيرها أيية، ولو كانت\nفاعلة لقيل: أوية، والرمز: الإشارة بالشفة.\nوالغمز بالعين والحاجب.\nوالإبكار: مصدر أبكر، يقال: أبكر وبكر وبكر\nوابتكر، والبكرة من وقت طلوع الفجر إلى ضحوة النهار.\nوقوله: ﴿ٱجۡعَل لِّيٓ ءَايَةٗۖ﴾⟪3:41⟫ قيل: طلب علامة لوقت الحمل.\nفجعل تعالى أن لا يمكنه مكالمة الناس إلا إيماء مع تمكنه من ذكر\nالله، وقيل: بل سأله أن يبين له قربة يجعلها شكرا لما خوله،\n⟦2:549⟧\nفأمره أن يجعل شكره الاشتغال بالعبادة، وترك مكالمة الناس إلا\nرمزا ثلاثة أيام، وهو المذكور في قوله: ﴿ثَلَٰثَ لَيَالٖ سَوِيّٗا﴾⟪19:10⟫.\nوفي هذا دليل أن في ذكر اليوم أو الليلة غنى عن ذكر الآخر عند\nالإطلاق، وإذا أريد الخلاف بمن حينئذ نحو ﴿سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ﴾⟪69:7⟫، وعلى هذا الآية عبارة عن الفريضة، فإن زكريا سأل\n⟦2:550⟧\nأن يفرض عليه فرضا يجعله شكرا له، وتسبيحه: قيل هو\nالصلاة، وسميت الصلاة سبحة.\nوقوله: ﴿بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ﴾⟪3:41⟫ قيل: عنى في هذه الأيام الثلاث.\nولم يعن التسبيح في طرفي النهار فقط، بل إنما أراد إدامة العبادة في هذه\nالأيام.\nوقرئ ﴿أَلَّا تُكَلِّمَ﴾⟪3:41⟫ بالرفع والنصب، نحو:\n⟦2:551⟧\n﴿وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ﴾⟪5:71⟫ بالرفع والنصب."}, {"a": [42], "v": 2, "p": 551, "ev": 2, "ep": 555, "sid": 753, "t": "قوله عز وجل: (وإذ قالت الملائكة يا مريم إن الله اصطفاك وطهرك واصطفاك على نساء العالمين (42)\nتكرير الاصطفاء قيل لمعنيين: الأول فرغها لعبادته وأغناها عن الكسب، والثاني أن جعلها أما لعيسى وآية له، وقيل الأول الاصطفاء الذي هو\n⟦2:552⟧\nالاجتباء. والثاني الاصطفاء الذي هو على سبيل الهداية، وقد\nتقدم ذكرهما آنفا.\nوتطهيرها قيل: من الحيض.\nوقيل: من نجاسة الكفر، كقوله تعالى: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ﴾⟪33:33⟫.\nوقول الملائكة لها قيل: كان بالإلهام، فإنه ما أوحى الله إلى\n⟦2:553⟧\nامرأة وحي النبوة، فلذلك قال:\n⟦2:554⟧\n﴿وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم﴾\nوقيل: بل قد أوحي إليهن ولكن لم يبعثن رسلا.\nوقال الجئائي: إنما يجوز أن يكون أوحي إليها معجزة\nلزكريا أو توطئة لنبوة المسيح، وقوله هذا إيماء لمذهبهم أن\n⟦2:555⟧\nالمعجزات والوحي لا تصح إلا في أزمنة الأنبياء عليهم الصلاة\nوالسلام، وذلك دفع منه لكرامة الأولياء، وقوله: ﴿عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ﴾⟪3:42⟫، قيل: هو على العموم، وقيل: عنى اللاتي في زمانها."}, {"a": [43], "v": 2, "p": 556, "ev": 2, "ep": 557, "sid": 758, "t": "قوله عز وجل: (يا مريم اقنتي لربك واسجدي واركعي مع الراكعين (43)\nالقنوت: إدامة الطاعة صلاة كانت أو غيرها من\nالعبادات، ولهذا قال: ﴿أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا﴾⟪39:9⟫\nفجعل من جملة القنوت، وتقديم السجود على الركوع.\nقيل: لكونه كذلك في شريعتهم، وقيل: تنبيها أن الواو لا تقتضي\nالترتيب، وقيل: عنى بالسجود الصلاة، لقوله: ﴿وَأَدۡبَٰرَ ٱلسُّجُودِ﴾⟪50:40⟫\nوعنى بالركوع الشكر، لقوله تعالى في قصة داود:\n﴿وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩﴾⟪38:24⟫ أي شاكرا، وهذا تخصيص للركوع بحال\nمقترنة به، وقيل: نبه بقوله: ﴿وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ﴾⟪3:43⟫ أي كوني\n⟦2:557⟧\nمع العابدين والمصلين، وخصها بفضل إيجاب اقتضاه قوله.:\n﴿ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي﴾⟪3:43⟫\nإن قيل: كيف أخر هذا الذكر لمريم عن ذكر قصتها؟\nقيل: لما ذكر آيتها قرن بها آية زكريا وعبادته، ثم أتبعها بعبادة مريم متمما لقصتها؛ لئلا يحتاج إلى قطع قصة زكريا، فيكون قد قرن ذكر الآية بالآية والعبادة بالعبادة."}, {"a": [44], "v": 2, "p": 557, "ev": 2, "ep": 559, "sid": 759, "t": "قوله عز وجل: (ذلك من أنباء الغيب نوحيه إليك وما كنت لديهم إذ يلقون أقلامهم أيهم يكفل مريم وما كنت لديهم إذ يختصمون (44)\n⟦2:558⟧\nقد تقدم أنواع الوحي، وأن أصله الإشارة، ويقال\nللكتابة: وحي، إذ هي إشارة ما، وقد يكون الوحي بالإلهام\nكما يكون بضرب من الكلام، وعلى ذلك قوله: ﴿وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي﴾⟪5:111⟫\nوقد يقال ذلك للوساوس نحو قوله: ﴿وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ﴾⟪6:121⟫\nوكثيرا ما يشبه الوساوس بالإلهام، فلا يميز بينهما إلا أولو العقول\nالراجحة.\nوالقلم: القص من الصلب كالظفر وكعب الرمح والقصب، ويقال للمقلوم: قلم، كقولهم للمنقوض: نقض،\n⟦2:559⟧\nوخص ذلك بما يكتب به وبالقدح، وأكد بقوله: ﴿وَمَا كُنتَ لَدَيۡهِمۡ﴾⟪3:44⟫\nأن هذا مما أبلغت من الغيب، لقوله عز وجل في قصة موسى: ﴿وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَيۡنَا﴾⟪28:46⟫\nوقوله: ﴿وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ﴾⟪28:45⟫\nومقارعتهم عليها:\nقال قتادة: كانوا من حرصهم على كفالتها يتقارعون عليها لفضلها.\nوقيل: لتدافعهم إشفاقا من أزمة كانوا فيها."}, {"a": [45], "v": 2, "p": 560, "ev": 2, "ep": 565, "sid": 762, "t": "قوله عز وجل: (إذ قالت الملائكة يا مريم إن الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيها في الدنيا والآخرة ومن المقربين (45)\nتسمية عيسى بالكلمة لقوله: ﴿ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ﴾⟪3:59⟫\nولفظة كن وإن كانت للأمر فموضوعة للابداع، وذاك أن\nفعل الله ضربان: عادي وإبداعي\nفالعادي ويسميه قوم الطبعي: هو الذي أجرى الله تعالى به العادة أن يكون في زمان ومكان، ومن أصل، وعلى وجه مخصوص وشيئا بعد شيء.\nكخلقة الولد من النطفة والزرع من البذر.\nوالإبداعي: ما يوجده\n⟦2:561⟧\nدفعة من غير حاجة إلى زمان ولا من أصل كخلق آدم بل كخلق\nالعالم. وعبر عن ذلك بكن إذ كان أسرع مفعول فيما بيننا ما كان\nقولا وأعم الألفاظ معنى الكون مع وجازة لفظ، وعلى ذلك قال:\n﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ﴾⟪16:40⟫\nوقال الأصم: سمي عيسى كلمة، لأنه تعالى خلق كلمة، فجعل منها عيسى، كما خلق آدم من تراب، وسائر الناس من نطفة، وهذا كما\nترى، وقال الجاحظ: وصفه بذلك من حيث إنه تقدم\nالإخبار به وبشارته في الكتب المتقدمة، وهذا كما سمى وعده\n⟦2:562⟧\nكلمة بقوله: ﴿حَقَّتۡ كَلِمَتُ رَبِّكَ﴾ وقوله: ﴿وَتَمَّتۡ كَلِمَتُ رَبِّكَ﴾ وقوله: ﴿وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ﴾⟪41:25⟫\nوقيل سمي كلمة؛ لكونه متكلما في المهد، وخص بذلك لفظ الكلمة للمبالغة: كوصف الفاعل بالمصدر.\nوقال النظام: جعل ذلك لقبا له لا لمعنى أشار إليه.\nوسمي مسيحا، لأنه مسح بالبركة.\n⟦2:563⟧\nوقيل: لأنه ماسحا للأرض لسياحته فيها، وقيل: لأنه مسح\nبالجمال، وعنى بذلك الجمال النفسي والبدني جميعا، من\nالأخلاق الجميلة والفضائل الكثيرة، نحو قول النبي - صلى الله عليه وسلم - في جرير \"عليه مسحة ملك \".\nوقيل: لأنه كان ممسوحا بالدهن\n⟦2:564⟧\nلما ولد\" وقيل: سمي به لأنه كان ممسوح القدمين لا أخمص\nلهما، وقيل: هو فعيل بمعنى فاعل، كأنه سمي به لأنه كان\nيمسح الأكمه والأبرص فيبرأ.\nوالجاه مقلوب عن الوجه،\n⟦2:565⟧\nلكن الوجه يقال في الحظوة وفي العضو، والجاه لا يقال إلا في\nالحظوة، ووجاهته: ما خص به من أوصافه المعلومة.\nوالقرب من الله تعالى في الدنيا: التخصيص بالصفات التي هي\nمن صفاته تعالى كالكرم والعفو والمغفرة، وفي الآخرة أن\nيصير في جواره، وقد تقدم ذلك."}, {"a": [46], "v": 2, "p": 565, "ev": 2, "ep": 567, "sid": 767, "t": "قوله عز وجل: (ويكلم الناس في المهد وكهلا ومن الصالحين (46)\nتكليمه الناس في المهد: ما أنبا عنه تعالى بقوله:\n⟦2:566⟧\n(إني عبد الله آتاني الكتاب وجعلني نبيا (30) وجعلني مباركا أين ما كنت) الآية، وذلك من الأفعال الإلهية، حيث جعل لطفل عقلا وعلما وكلاما.\nوقوله: (وكهلا) قيل: معناه كلامه في حال طفولته وكهولته سواء.\nوقيل: يكلمهم طفلا، وبعد نزوله من السماء كهلا، لأنه رفع قبل أن اكتهل.\nوقيل: يكلم الناس في المهد بكلام الكهول عقلا.\nوقوله: ﴿وَمِنَ ٱلصَّٰلِحِينَ﴾⟪3:46⟫ أي هومن جملة المذكورين في قوله: ﴿وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ﴾⟪4:69⟫.\nوموضع: (ويكلم)، نصب، كقول الشا عر:\n⟦2:567⟧\nيقصر يمشي ويطول باركا\nأي ماشيا."}, {"a": [47], "v": 2, "p": 567, "ev": 2, "ep": 569, "sid": 769, "t": "قوله عز وجل: (قالت رب أنى يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء إذا قضى أمرا فإنما يقول له كن فيكون (47)\nالقضاء: الفصل، وذلك إما بالتدبير، وإما بالقول، وإما بالفعل.\nفالأول لا يصح على الله عز وجل إلا بمعنى الحكم إذ كان\nالتدبير: التفكر في الشيء وارتياد الصلاح فيه، وذلك لمن كان\nناقص العلم، فقوله: قضى، ها هنا إما للقول، وإما للفعل.\nأولهما جميعا، ومعنى قوله: (كن) أي يبدعه على ما تقدم،\n⟦2:568⟧\nوقال الأصم: عادة الله جارية فيما أخبر عن كونه، أن يقول في\nوقت ما يحدثه كن كخلقه لآدم كما قال للملائكة ﴿إِنِّي خَٰلِقُۢ بَشَرٗا﴾\nقال له: كن. لما أراد إحداثه تنبيها لهم، وكذلك لما\nأخبر أنه سيبعث نبيا خلقه من غير ذكر، قال له: كن لما أراد\nإحداثه، وذلك ليعرف الملائكة انتهاء الأجل ونزوله.\nوقال أبو الهذيل إن ذلك قوله يقوله عند كل مكون.\nوحكي عنه أنه يجري مجرى الإرادة،\n⟦2:569⟧\nقالت رب أنى يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء إذا قضى أمرا فإنما يقول له كن فيكون (47)\nفقوله: ﴿أَنَّىٰ يَكُونُ لِي وَلَدٞ﴾⟪3:47⟫ تعجب منها لما ذكره لها من أمره\nبها، وكيف لا تتعجب وأمرها أبدع من أمر زكريا، فأجابها\nبقوله: (كذلك)، فمن وقف عليه جعل ما بعده كالتفسير\nله، ومن وصل: فمعناه أن الله كذا قضى أو كذا يفعل.\nإن قيل: لم قال ها هنا: ﴿يَخۡلُقُ مَا يَشَآءُۚ﴾⟪3:47⟫ وفي قصة زكريا: ﴿يَفۡعَلُ مَا يَشَآءُ﴾؟ قيل: لما كان الخلق أخص من الفعل خصه، بما هو إبداع.\nوذكر الفعل فيما هو أقرب إلى المعتاد في إيجاده."}];
